    "id": "nu545-e6-guide-2-ch41",
    "h": "Guide 2 · disorders of GI tract and accessory organs of digestion: pathophysiology, etiology, prevention, clinical manif",
    "html": "<p>Compare disorders by the disrupted function: an obstructed lumen prevents flow; an incompetent sphincter permits reflux; pancreatic enzyme loss impairs digestion; villous injury impairs absorption. Inflammatory bowel lesions differ in continuity and depth. Accessory-organ disease can change bile flow, hepatocyte processing or pancreatic enzyme delivery. The chapter cards below teach the supplied manifestations and broad treatments.</p>",
