    "id": "nu545-e6-guide-20-ch41",
    "h": "Guide 20 · cystic fibrosis (effects on the GI system)",
    "html": "<p>In cystic fibrosis, very thick mucus obstructs pancreatic ducts and limits digestive enzyme delivery. Pancreatic insufficiency produces maldigestion, especially of fat; growth failure can follow. The packet lists pancreatic enzyme replacement, high-calorie/high-protein intake and supplements. Pancreatic damage can involve beta cells and glucose regulation.</p>",
