    "id": "nu545-e6-topic-42-pediatric-nutrition-and-mucosal-emergencies",
    "h": "Pediatric nutrition and mucosal emergencies",
    "html": "<p>Marasmus is deficiency of all nutrients; kwashiorkor emphasizes severe protein deficiency. Use those supported definitions rather than the inconsistent slide60 labels. Faltering growth has biologic, psychosocial and environmental causes; the supplied approach addresses both underlying disease and feeding context. NEC combines immature barrier and ischemic/inflammatory injury and may perforate the bowel. The packet lists stopping feeds, decompression, fluids/electrolytes, antibiotics and selected surgery. These are source-depth concepts, not a neonatal treatment protocol.</p>",
    "c": [],
