    "id": "nu545-e6-topic-42-newborn-bilirubin-and-bile-drainage",
    "h": "Newborn bilirubin and bile drainage",
    "html": "<p>The packet distinguishes benign transient first-week jaundice from pathologic concerns such as appearance within the first day. Toxic unconjugated bilirubin can enter the brain and produce kernicterus. Phototherapy and selected exchange transfusion are named interventions, but the slide wavelength wording is excluded. Biliary atresia obstructs extrahepatic drainage and causes jaundice; surgical drainage and liver transplantation are listed. Numeric thresholds and treatment selection require the missing textbook or instructor clarification.</p>",
    "c": [],
