    "h": "Guide 25 · bone growth in children",
    "html": "<p>Primary ossification centers develop in the diaphysis and secondary centers in the epiphyses. Growth continues at the physeal plate through endochondral ossification until closure unites epiphysis and metaphysis. Nutrition, general health, growth hormone and growth regulators influence the process.</p>",
