    "id": "nu545-e6-guide-33-ch43",
    "h": "Guide 33 · osteoporosis: pathophysiology, etiology, prevention, clinical manifestations, diagnostics. What you will see o",
    "html": "<p>Osteoporosis reduces bone mass and structural integrity through imbalance between resorption and formation. Hormone loss, inactivity and glucocorticoid effects on RANKL/OPG are supplied contributors. Fractures, height loss and kyphosis are manifestations; weightbearing activity and sufficient mineral intake are prevention measures in the packet.</p>",
    "c": [],
