    "html": "<p>Articular cartilage pads bony surfaces; synovial membrane lines the capsule; synovial fluid lubricates and nourishes. Tendons join muscle to bone and ligaments join bone to bone. Bursae are synovial-lined, fluid-filled sacs among tendons, muscles and bony prominences.</p>",
