    "id": "nu545-e6-guide-45-ch43",
    "h": "Guide 45 · all parts of a muscle’s contraction.",
    "html": "<p>Excitation carries the action potential into the muscle; t-tubule signaling opens calcium-release channels. Coupling makes actin available to bind myosin. Cross-bridge action shortens the sarcomere; relaxation follows detachment and calcium return to the sarcoplasmic reticulum.</p>",
