    "id": "nu545-e6-guide-49-ch43",
    "h": "Guide 49 · muscle weight.",
    "html": "<p>The packet contrasts muscle as about 25% of infant body weight with 40% in adults. Muscle distribution changes with growth; fibers enlarge as fibrils become more numerous. Separately, the muscle tissue composition is about 75% water and 20% protein. Do not confuse tissue composition with percentage of body weight.</p>",
    "c": [],
