    "h": "Guide 51 · osteomyelitis: pathophysiology, etiology, clinical manifestations",
    "html": "<p>Osteomyelitis is bone infection that can spread beneath periosteum and into marrow. Loss of blood supply creates dead bone (sequestrum), while new periosteal bone is involucrum. Infants can stop moving a limb; older children can develop fever, swelling and reduced weightbearing.</p>",
