    "id": "nu545-e6-guide-27-ch45",
    "h": "Guide 27 · Duchenne muscular dystrophy: pathophysiology, etiology, clinical manifestations, diagnostics, and complication",
    "html": "<p>DMD affects dystrophin, which anchors the actin cytoskeleton to the basement membrane. Poor anchorage allows contraction-related membrane injury, calcium entry and fiber necrosis. Progressive weakness, Gower sign, respiratory insufficiency and cardiomyopathy are listed. Enlarged calves can reflect fat/connective tissue rather than effective muscle (slide61 notes).</p>",
