   "evidenceExcerpt": "CH40S34\nSmall Intestine\n(3 of 5)\nMuscle layers\nOuter: Longitudinal\nInner: Circular \nMucosal folds\nVilli \nFunction:  Absorption\nMicrovilli\nBrush border\nGreatly increases absorption surface area\n34\nSpeaker notes: \n\nCH40S35\nSmall Intestine\n(4 of 5)\nLamina propria\nIs a connective tissue layer of the mucosa.\nContains lymphocytes and plasma cells.\nLacteals\nLymphatic capillaries contained in each villus.\nFat molecules are absorbed and transported.\nContents of lacteals flow to the regional nodes and channels, eventually draining into the thoracic duct.\n35\nSpeaker notes: \n\nCH40S36\nSmall Intestine\n(5 of 5)\nCrypts of Lieberkühn\nLie between the bases of the villi. \nColumnar epithelial secretory cells\nWater\nElectrolytes\nEnzymes\nGoblet cells\nMucous\n36\nSpeaker notes: ",
