   "explain": "Emulsification keeps smaller fat droplets from reforming.",
   "decision": "emulsify",
   "evidenceExcerpt": "CH40S42\nIntestinal Digestion and Absorption\n(6 of 9)\nFats\nEmulsification\nEmulsifying agents cover the small fat particles and prevent them from re-forming into fat droplets.\nFats are then ready for lipolysis (lipid hydrolysis). \nLipase breaks down triglycerides into diglycerides, monoglycerides, free fatty acids, and glycerol.\nPhospholipase cleaves fatty acids from phospholipids.\nCholesterol esterase breaks cholesterol esters into fatty acids and glycerol.\n42\nSpeaker notes: \n\nCH40S43\nIntestinal Digestion and Absorption\n(7 of 9)\nFats (cont.)\nMicelle formation\nMust be made water soluble to be absorbed. \nIs accomplished by the formation of water-soluble molecules (micelles).\nFat absorption\nResynthesized triglycerides and phospholipids\nAbsorbed as chylomicrons into the lacteals.\n43\nSpeaker notes: \n\nCH40S62\nSecretion of Bile\n(1 of 2)\nAlkaline, bitter-tasting, yellowish green fluid that contains bile salts, cholesterol, bilirubin, electrolytes, and water\nBile salts: Conjugated bile acids that are required for the intestinal emulsification and absorption of fats\nFormed by hepatocytes and secreted into the bile canaliculi\nBile acid pool: Primary vs. secondary bile acids\n62\nSpeaker notes: ",
