   "decision": "enzyme bond",
   "evidenceExcerpt": "CH40S41\nIntestinal Digestion and Absorption\n(5 of 9)\nProteins\nPancreatic enzymes accomplish major protein hydrolysis in the small intestine.\nTrypsin and chymotrypsin: Hydrolyze the interior bonds of the large molecules (endopeptidases).\nCarboxypeptidase: Breaks away the end amino acids (exopeptidase).\nSodium-dependent carrier actively transports amino acids from the cytosol into the bloodstream.\nFree amino acids can be absorbed directly from the intestinal lumen using a membrane transport protein.\n41\nSpeaker notes: ",
