   "tier": 1,
   "pool": "mock",
   "explain": "K deficiency is linked to prolonged prothrombin time.",
   "decision": "bile deficit",
   "evidenceExcerpt": "CH41S58\nMalabsorption Syndromes\n(4 of 5)\nBile salt deficiency\nConjugated bile salts are needed to emulsify and absorb fats and are synthesized from cholesterol in the liver.\nIs the result of liver disease, intestinal stasis, disease/resection of ileum, and bile obstructions.\nPoor intestinal absorption of lipids causes fatty stools, diarrhea, decreased plasma proteins, and loss of fat-soluble vitamins (A, D, E, K).\nTreatment\nIncrease medium-chain triglycerides in the diet.\nParenterally administer vitamins A, D, and K.\nCholestyramine\n \n58\nSpeaker notes: \n\nCH41S59\nMalabsorption Syndromes\n(5 of 5)\nFat-soluble vitamin deficiencies\nVitamin A\nNight blindness\nVitamin D\nDecreased calcium absorption, bone pain, osteoporosis, fractures\nVitamin K\nProlonged prothrombin time, purpura, and petechiae\nVitamin E\nTesticular atrophy \nNeurologic defects in children\n59\nSpeaker notes: \n\nCH40S69\nMetabolism of Nutrients\n(3 of 3)\nMetabolizes fats.\nLiver produces bile to absorb fat-soluble vitamins.\nHydrolyzed triglycerides produce metabolic energy (adenosine triphosphate [ATP]) or are released into the bloodstream bound to proteins (lipoproteins).\nSynthesizes phospholipids and cholesterol.\n69\nSpeaker notes: ",
