   "explain": "The lower sphincter prevents regurgitation from stomach.",
   "decision": "sphincter",
   "evidenceExcerpt": "CH40S15\nMouth and Esophagus\n(3 of 7)\nEsophagus\nIs the hollow muscular tube that measures approximately 25 cm long and conducts substances from the oropharynx to the stomach.\nUpper esophageal sphincter (cricopharyngeal muscle) prevents the entry of air into the esophagus during respiration.\nLower esophageal sphincter (LES) was formerly called cardiac sphincter. \nPrevents regurgitation from the stomach.\nServes as a barrier between the stomach and the esophagus.\n15\nSpeaker notes: \n\nCH40S21\nStomach\n(2 of 3)\nSphincters\nLower esophageal sphincter\nPyloric sphincter: Allows food to exit the stomach into the duodenum\nFunctional portions\nFundus: Upper\nBody: Middle\nAntrum: Lower\n21\nSpeaker notes: \n\nCH40S32\nSmall Intestine\n(1 of 5)\nBetween 5 and 6 m long\nThree segments\nDuodenum\nJejunum\nIleum\nIleocecal valve: Controls the flow of digested material from the ileum into the large intestine and prevents reflux into the small intestine. \n32\nSpeaker notes: \n\nCH40S50\nLarge Intestine\n(3 of 7)\nIleocecal valve\nAdmits chyme from the ileum to the cecum.\nO’Beirne sphincter\nControls the movement of wastes from the sigmoid colon into the rectum.\nInternal anal sphincter\nSmooth muscle of anal canal\nExternal anal sphincter\nStriated skeletal muscle\n50\nSpeaker notes: ",
