   "evidenceExcerpt": "CH40S14\nMouth and Esophagus\n(2 of 7)\nSalivary glands\nThree pairs\nSubmandibular\nSublingual\nParotid\nSaliva\nIs composed of water with mucus, sodium, bicarbonate, chloride, potassium, and salivary \nα\n-amylase (carbohydrate digestion).\nIs controlled by sympathetic (increases) and parasympathetic (decreases) fibers.\nContains immunoglobulin A (IgA).\n14\nSpeaker notes: \n\nCH40S55\nIntestinal Microbiome\nStomach environment is relatively sterile because of secreted stomach acid.\nBile acid secretion, motility, and antibody production keep bacterial numbers in the duodenum to a minimum.\nA low concentration of aerobes are in the jejunum.\nAnaerobic bacteria are distal to the ileocecal valve.\n55\nSpeaker notes: ",
