   "decision": "ileal gate",
   "evidenceExcerpt": "CH40S32\nSmall Intestine\n(1 of 5)\nBetween 5 and 6 m long\nThree segments\nDuodenum\nJejunum\nIleum\nIleocecal valve: Controls the flow of digested material from the ileum into the large intestine and prevents reflux into the small intestine. \n32\nSpeaker notes: \n\nCH40S50\nLarge Intestine\n(3 of 7)\nIleocecal valve\nAdmits chyme from the ileum to the cecum.\nO’Beirne sphincter\nControls the movement of wastes from the sigmoid colon into the rectum.\nInternal anal sphincter\nSmooth muscle of anal canal\nExternal anal sphincter\nStriated skeletal muscle\n50\nSpeaker notes: ",
