   "tier": 1,
   "pool": "mock",
   "explain": "Alcohol is named among the few stomach-absorbed substances.",
   "decision": "stomach absorption",
   "evidenceExcerpt": "CH40S22\nStomach\n(3 of 3)\nFew substances absorbed in the stomach\nCan absorb alcohol, aspirin, other nonsteroidal antiinflammatory agents\nImpermeable to water\nSwallowing\nCauses the fundus to relax.\nCoordinated by efferent, \nnonadrenergic\n, noncholinergic vagal fibers\n22\nSpeaker notes: \n\nCH40S39\nIntestinal Digestion and Absorption\n(3 of 9)\nWater and electrolytes\nAre transported in both directions (toward the capillary blood or toward the intestinal lumen) through the tight junctions and intercellular spaces rather than across cell membranes.\nApproximately 85% to 90% of water is absorbed in the small intestine.\n39\nSpeaker notes: \n\nCH40S40\nIntestinal Digestion and Absorption\n(4 of 9)\nCarbohydrates\nComplex carbohydrates (polysaccharides and oligo-saccharides) must be hydrolyzed to their simplest form. \nSalivary and pancreatic amylases breakdown starches.\nSugars are primarily absorbed in the duodenum and in the upper jejunum.\nGlucose transporter (GLUT2) facilitates the transportation of all three monosaccharides from the cytosol to the bloodstream.  \nHumans lack the enzymes to digest cellulose.\n40\nSpeaker notes: \n\nCH40S41\nIntestinal Digestion and Absorption\n(5 of 9)\nProteins\nPancreatic enzymes accomplish major protein hydrolysis in the small intestine.\nTrypsin and chymotrypsin: Hydrolyze the interior bonds of the large molecules (endopeptidases).\nCarboxypeptidase: Breaks away the end amino acids (exopeptidase).\nSodium-dependent carrier actively transports amino acids from the cytosol into the bloodstream.\nFree amino acids can be absorbed directly from the intestinal lumen using a membrane transport protein.\n41\nSpeaker notes: \n\nCH40S42\nIntestinal Digestion and Absorption\n(6 of 9)\nFats\nEmulsification\nEmulsifying agents cover the small fat particles and prevent them from re-forming into fat droplets.\nFats are then ready for lipolysis (lipid hydrolysis). \nLipase breaks down triglycerides into diglycerides, monoglycerides, free fatty acids, and glycerol.\nPhospholipase cleaves fatty acids from phospholipids.\nCholesterol esterase breaks cholesterol esters into fatty acids and glycerol.\n42\nSpeaker notes: \n\nCH40S43\nIntestinal Digestion and Absorption\n(7 of 9)\nFats (cont.)\nMicelle formation\nMust be made water soluble to be absorbed. \nIs accomplished by the formation of water-soluble molecules (micelles).\nFat absorption\nResynthesized triglycerides and phospholipids\nAbsorbed as chylomicrons into the lacteals.\n43\nSpeaker notes: ",
