   "evidenceExcerpt": "CH41S33\nDisorders of Motility\n(11 of 17)\nIntestinal obstruction and ileus\nIntestinal obstruction: Any condition that prevents the flow of chyme through the intestinal lumen or failure of normal intestinal motility in the absence of an obstructing lesion\nClinical manifestations\nSmall intestine obstruction: Colicky pains caused by intestinal distention, followed by nausea and vomiting\nLarge intestine obstruction: Hypogastric pain and abdominal distention\n33\nSpeaker notes: \n\nCH41S34\nDisorders of Motility\n(12 of 17)\nIntestinal obstruction and ileus (cont.)\nTreatment\nReplacement of fluid and electrolytes\nGastric or intestinal suction\nAdhesions: Laparoscopic procedures \nStrangulation and complete obstruction: Immediate surgical intervention\nMalignant obstruction: Colonic stent\nColonic pseudo-obstruction: Neostigmine, a parasympathomimetic and \ncolonoscopic\n decompression\nIntestinal perforation: IV antibiotics, fluid resuscitation, surgery\n34\nSpeaker notes: \n\nCH41S35\nDisorders of Motility\n(13 of 17)\nIntestinal obstruction and ileus (cont.)\nType of \nvomitus\n:  Can indicate the location of the obstruction\n35\nSpeaker notes: \n\nCH41S36\nDisorders of Motility\n(14 of 17)\nIntestinal obstruction and ileus (cont.)\nPylorus\nEarly, profuse vomiting of clear gastric fluid\nProximal small intestine\nMild distention and vomiting of bile-stained fluid\nLower in small intestine\nMore pronounced distention because a greater length of intestine is proximal to the obstruction\nVomiting may not occur or may occur later and contain fecal material\n36\nSpeaker notes: \n\nCH41S37\nDisorders of Motility\n(15 of 17)\nIntestinal obstruction and ileus (cont.)\nSimple obstruction\nPresence of a lesion\nFunctional obstruction: Paralytic ileus\nFailure of motility, especially after surgery\n37\nSpeaker notes: \n\nCH41S38\nDisorders of Motility\n(16 of 17)\nSmall intestinal obstruction\nMost common: Fibrous adhesions\nLarge bowel obstruction\nMost common: Colorectal cancer, volvulus (twisting), and strictures related to diverticulitis\nAcute colonic pseudo-obstruction (Ogilvie syndrome): Massive dilation of the large bowel; patients who are critically ill and older adults who are immobilized\n38\nSpeaker notes: ",
