   "tier": 1,
   "pool": "practice",
   "explain": "Loss of reservoir/emptying control permits rapid hypertonic delivery.",
   "decision": "emptying loss",
   "evidenceExcerpt": "CH41S53\nPeptic Ulcer Disease\n(9 of 10)\nDumping syndrome\nRapid emptying of hypertonic chyme from the stomach into the small intestine \nComplication of partial gastrectomy, bariatric procedure, or pyloroplasty\nDevelopmental factors for early dumping\nLoss of gastric capacity, loss of emptying control, and loss of feedback control by the duodenum when it is removed \nClinical manifestations\nDiarrhea, cramping, feeling of epigastric fullness, pain, nausea, and vomiting\n53\nSpeaker notes: \n\nCH41S54\nPeptic Ulcer Disease\n(10 of 10)\nDumping syndrome (cont.)\nLate dumping syndrome (1–3 hours after eating)\nClinical manifestations\nWeakness, diaphoresis, and confusion\nTreatment for early and late dumping\nConsuming frequent small meals high in protein and low in carbohydrates \nDrinking fluids between meals instead of at mealtime\nReclining on the left side after eating\nReconstructing the pylorus or a gastrojejunostomy\nAdministering \nOctreotide\n: To inhibit insulin release and slow intestinal transit time\n54\nSpeaker notes: \n\nCH41S26\nDisorders of Motility\n(4 of 17)\nGastroesophageal reflux disease (GERD)\nAcid and pepsin reflux from the stomach into the esophagus, causing esophagitis.\nResting tone of the lower esophageal sphincter tends to be lower than normal from either transient relaxation or weakness of the sphincter.\nConditions that increase abdominal pressure can contribute to GERD.\nVomiting, coughing, lifting, bending, obesity, or pregnancy \n26\nSpeaker notes: \n\nCH41S57\nMalabsorption Syndromes\n(3 of 5)\nLactase deficiency\nCongenital defect in the lactase gene \nInability to breakdown lactose into monosaccharides and thus prevent lactose digestion and monosaccharide absorption\nFermentation of lactose by bacteria, causing gas (cramping pain, flatulence) and osmotic diarrhea\nTreatment\nAvoidance of milk products; adherence to a lactose-free diet \nMaintenance of adequate calcium intake to decrease risk of osteoporosis\nLactase enzyme replacement\n57\nSpeaker notes: \n\nCH40S51\nLarge Intestine\n(4 of 7)\nTaenia coli\nIs a longitudinal muscle layer that consists of three longitudinal bands. \nHaustra\nCircular muscles of the colon separate the gathers into outpouchings. \nPrimary type of colonic movement\nIs segmental.\nPeristaltic movements \nPromote emptying of the colon.\n51\nSpeaker notes: ",
