   "explain": "Intrinsic factor loss impairs B12 uptake.",
   "decision": "autoimmune anemia",
   "evidenceExcerpt": "CH41S42\nGastritis\n(3 of 5)\nChronic antral gastritis\nNonimmune\nType B\nAssociated \nwith \nH. pylori\n, NSAIDs, alcohol, tobacco.\nChronic fundal gastritis\nImmune\nType A\nAssociated with autoantibodies to parietal cells and intrinsic factor, resulting in gastric atrophy and pernicious anemia.\n42\nSpeaker notes: \n\nCH40S30\nGastric Secretion\n(6 of 7)\nMucus\nProstaglandins and nitric oxide: Protect the mucosal barrier. \nIntrinsic factor: \nMucoprotein\n that combines with vitamin B12; help ileum absorb B12\nFailure to absorb B12 results in anemia\nPhases of gastric secretion\nCephalic\nGastric \nIntestinal\n30\nSpeaker notes: \n\nCH40S63\nSecretion of Bile\n(2 of 2)\nEnterohepatic circulation\nRecycling of bile salts\nAlso called choleresis\nCholeretic agent: Substance that stimulates the liver to secrete bile\nStrong stimulus: High concentration of bile salts\nOther choleretic agents: Secretin, cholecystokinin, vagal stimulation\n63\nSpeaker notes: \n\nCH40S73\nExocrine Pancreas\n(2 of 2)\nEnzymes\nTrypsinogen, \nchymotrypsinogen\n, and \nprocarboxypeptidase\nInactivates proteases\nIs activated by enterokinase\nTrypsin inhibitor\nPrevents the pancreas from eating itself\nEnterokinase\nActivates proenzymes in the duodenum\nPancreatic a-amylase\nDigests carbohydrate\nPancreatic lipase\nDigests fat\n73\nSpeaker notes: \n\nCH42S58\nPrimary Lactose Intolerance\n(1 of 3)\nInability to digest milk sugar (lactose)\nCause: Inadequate production of lactase, the enzyme that catabolizes lactose\nMalabsorbed lactose: Causes osmotic diarrhea, abdominal pain, bloating, flatulence \n58\nSpeaker notes: ",
