   "evidenceExcerpt": "CH41S26\nDisorders of Motility\n(4 of 17)\nGastroesophageal reflux disease (GERD)\nAcid and pepsin reflux from the stomach into the esophagus, causing esophagitis.\nResting tone of the lower esophageal sphincter tends to be lower than normal from either transient relaxation or weakness of the sphincter.\nConditions that increase abdominal pressure can contribute to GERD.\nVomiting, coughing, lifting, bending, obesity, or pregnancy \n26\nSpeaker notes: \n\nCH41S27\nDisorders of Motility\n(5 of 17)\nGERD (cont.)\nClinical manifestations\nHeartburn from acid regurgitation, chronic cough, laryngitis, asthma attacks, sinusitis\nUpper abdominal pain within 1 hour of eating\nEvaluation\nBiopsy: Dysplastic changes (Barrett esophagus) \nTreatment\nProton pump inhibitors: Most effective\nHistamine type 2 (H2) receptor antagonists, prokinetic agents, and antacids; pain medication \nElevate head of the bed 6 inches; reduce weight; stop smoking.\nSurgery: Laparoscopic fundoplication\n27\nSpeaker notes: ",
