   "decision": "lesion depth",
   "evidenceExcerpt": "CH41S61\nInflammatory Bowel Disease\n(2 of 8)\nUlcerative colitis\nIs a chronic inflammatory disease that causes ulceration of the colonic mucosa. \nSigmoid colon and rectum\nIs common in those 20–40 years of age.\nPathophysiology\nLesions are continuous with no skipped lesions, are limited to the mucosa, and are not transmural.\n61\nSpeaker notes: \n\nCH41S64\nInflammatory Bowel Disease\n(5 of 8)\nCrohn disease\nGranulomatous colitis, ileocolitis, or regional enteritis\nIdiopathic inflammatory disorder; affects any part of the digestive tract, from mouth to anus\nDifficult to differentiate from ulcerative colitis\nSimilar risk factors and theories of causation\nStrong association\nNucleotide-binding oligomerization domains (\nCARD15\n/\nNOD2\n) gene mutations\n64\nSpeaker notes: \n\nCH41S65\nInflammatory Bowel Disease\n(6 of 8)\nCrohn disease (cont.)\nCauses “skip” lesions.\nInflamed areas mixed with uninflamed areas, \nnoncaseating\n granulomas, fistulas, deep penetrating ulcers\nClinical manifestations\nRectal bleeding and diarrhea are the most common signs; abdominal tenderness, anemia.\nAnemia may develop as a result of malabsorption of vitamin B12 and folic acid.\n65\nSpeaker notes: \n\nCH41S57\nMalabsorption Syndromes\n(3 of 5)\nLactase deficiency\nCongenital defect in the lactase gene \nInability to breakdown lactose into monosaccharides and thus prevent lactose digestion and monosaccharide absorption\nFermentation of lactose by bacteria, causing gas (cramping pain, flatulence) and osmotic diarrhea\nTreatment\nAvoidance of milk products; adherence to a lactose-free diet \nMaintenance of adequate calcium intake to decrease risk of osteoporosis\nLactase enzyme replacement\n57\nSpeaker notes: \n\nCH41S68\nIrritable Bowel Syndrome\n(1 of 3)\nFunctional gastrointestinal disorder with no specific structural or biochemical alterations\nPathophysiology\nVisceral hypersensitivity or hyperalgesia\nAbnormal gastrointestinal permeability, motility, secretion, and sensitivity\nPostinflammatory\n irritable bowel syndrome\nAlteration in gut microbiota \nFood allergy or food intolerance\nPsychosocial factors\n68\nSpeaker notes: ",
