   "tier": 1,
   "pool": "mock",
   "explain": "Inflamed diverticula produce the stated systemic signs.",
   "decision": "diverticula",
   "evidenceExcerpt": "CH41S38\nDisorders of Motility\n(16 of 17)\nSmall intestinal obstruction\nMost common: Fibrous adhesions\nLarge bowel obstruction\nMost common: Colorectal cancer, volvulus (twisting), and strictures related to diverticulitis\nAcute colonic pseudo-obstruction (Ogilvie syndrome): Massive dilation of the large bowel; patients who are critically ill and older adults who are immobilized\n38\nSpeaker notes: \n\nCH41S68\nIrritable Bowel Syndrome\n(1 of 3)\nFunctional gastrointestinal disorder with no specific structural or biochemical alterations\nPathophysiology\nVisceral hypersensitivity or hyperalgesia\nAbnormal gastrointestinal permeability, motility, secretion, and sensitivity\nPostinflammatory\n irritable bowel syndrome\nAlteration in gut microbiota \nFood allergy or food intolerance\nPsychosocial factors\n68\nSpeaker notes: \n\nCH41S69\nIrritable Bowel Syndrome\n(2 of 3)\nClinical manifestations\nLower abdominal pain\nDiarrhea-predominant, constipation-predominant, or alternating diarrhea and constipation\nGas, bloating\nNausea\n69\nSpeaker notes: \n\nCH41S70\nIrritable Bowel Syndrome\n(3 of 3)\nTreatment\nNo available cure\nLaxatives, soluble fiber\nRestriction of gluten, FODMAPs\nAntidiarrheals\nAntispasmodics\nPro-secretory drugs\nVisceral analgesics\nLow-dose antidepressants\nSerotonin agonists/antagonists\nAntibiotics\n70\nSpeaker notes: \n\nCH41S71\nDiverticular Disease of the Colon\n(1 of 2)\nDiverticula\nHerniation of mucosa through the muscle layers of the colon wall\nDiverticulosis\nAsymptomatic diverticular disease\nDiverticulitis\nInflammatory stage of diverticulosis\nPredisposing factors\nOlder age, genetics, obesity, smoking, diet, lack of physical activity, and medications\n71\nSpeaker notes: \n\nCH41S72\nDiverticular Disease of the Colon\n(2 of 2)\nClinical manifestations\nLow cramping abdominal pain, diarrhea, constipation, distension, flatulence\nDiverticulitis: Fever, leukocytosis\nTreatment\nIncrease of dietary fiber intake to increase stool weight, lower colonic pressures, improve transit times, and relieve symptoms\nUncomplicated diverticular disease: Bowel rest and antibiotic administration\nSurgical resection\n72\nSpeaker notes: ",
