   "explain": "Maldigestion is failed chemical processing.",
   "decision": "digest v absorb",
   "evidenceExcerpt": "CH41S55\nMalabsorption Syndromes\n(1 of 5)\nInterfere with nutrient absorption\nMaldigestion\nFailure of the chemical processes of digestion\nMalabsorption\nFailure of the intestinal mucosa to absorb (transport) the digested nutrients\n55\nSpeaker notes: \n\nCH41S56\nMalabsorption Syndromes\n(2 of 5)\nPancreatic insufficiency\nInsufficient pancreatic enzyme production\nLipase, amylase, trypsin, or chymotrypsin\nCauses: Pancreatitis, pancreatic carcinoma, pancreatic resection, and cystic fibrosis\nFat maldigestion: Primary problem\nMost common signs: Fatty stools (steatorrhea); weight loss\nTreatment: Lipase supplements\n56\nSpeaker notes: ",
