   "evidenceExcerpt": "CH41S86\nHepatic Encephalopathy\n(1 of 2)\nComplex neurological syndrome characterized by impaired behavioral, cognitive, and motor function\nClinical manifestations\nPersonality changes\nConfusion\nIrritability\nLethargy\nSleep disturbances\nFlapping tremor (asterixis)\nStupor, coma, death\n86\nSpeaker notes: ",
