   "evidenceExcerpt": "CH41S103\nViral Hepatitis\n(1 of 5)\nHepatitis A\nCan be found in the feces, bile, and sera of infected individuals.\nIs usually transmitted by the fecal-oral route.\nRisk factors\nCrowded, unsanitary conditions\nFood and water contamination\nPrevention\nHandwashing\nAdministration of immunoglobulin before exposure or early in the incubation period \nAdministration of vaccines\n103\nSpeaker notes: \n\nCH41S104\nViral Hepatitis\n(2 of 5)\nHepatitis B\nParenterally and sexually transmitted\nMaternal transmission occurs if the mother is infected during the third trimester.\nHepatitis B vaccine prevents the transmission and development of hepatitis B.\nHepatitis B immunoglobulin provides post-exposure prophylaxis against hepatitis B.\n104\nSpeaker notes: \n\nCH41S105\nViral Hepatitis\n(3 of 5)\nHepatitis C\nIs responsible for most cases of posttransfusion hepatitis.\nIs also implicated in infections related to IV drug use and human immunodeficiency viral (HIV) infection.\nCo-infection with hepatitis B is common.\nApproximately 80% of those with hepatitis C develop chronic liver disease.\nNo vaccine is available.\nAdminister antiviral medications. \n105\nSpeaker notes: \n\nCH41S106\nViral Hepatitis\n(4 of 5)\nHepatitis D\nDependent on hepatitis B for replication\nTreatment: Pegylated interferon alpha \nHepatitis E\nFecal-oral transmission\nContaminated water or uncooked meat\nMost common in Asian and African countries\nVaccine in China but not in other countries\n106\nSpeaker notes: ",
