   "tier": 1,
   "pool": "practice",
   "explain": "Muscle hypertrophy encroaches on the lumen.",
   "decision": "pylorus",
   "evidenceExcerpt": "CH42S12\nInfantile Hypertrophic Pyloric Stenosis\n(1 of 5)\nObstruction of the pyloric sphincter is caused by hypertrophy of the sphincter muscle.\nRisk factors\nIncreased gastrin secretion by the mother in the last trimester \nOverproduction of gastric secretions in the infant that may be caused by stress-related factors in the mother\nExogenous administration of prostaglandin E \nIncreased risk factors if a family member has had pyloric stenosis\n12\nSpeaker notes: \n\nCH42S13\nInfantile Hypertrophic Pyloric Stenosis\n(2 of 5)\nCircular muscle of the pylorus is grossly enlarged.\nHypertrophy: Increased cell size \nHyperplasia: Increased number of cells\nMucosal lining of the pyloric opening is folded, and the lumen is narrowed by the encroaching muscle.\nAs a result of the extra peristaltic effort needed to force gastric contents through the narrow pylorus, the stomach muscle layers may become hypertrophied.\n13\nSpeaker notes: \n\nCH42S14\nInfantile Hypertrophic Pyloric Stenosis\n(3 of 5)\nClinical manifestations\nProjectile vomiting after feeding\nVomiting causes weight loss, fluid and electrolyte imbalances, chronic malnutrition, and dehydration.\nCan be fatal within 4–6 weeks.\n14\nSpeaker notes: \n\nCH42S15\nInfantile Hypertrophic Pyloric Stenosis\n(4 of 5)\nTreatment\nPyloromyotomy: Muscles of the pylorus are split and separated.\nFluid and electrolyte losses are managed before surgical intervention.\nChildren can usually tolerate feeding several hours after surgery.\n15\nSpeaker notes: ",
