   "explain": "Mesenteric constriction first impairs venous return.",
   "decision": "telescoping",
   "evidenceExcerpt": "CH42S31\nIntussusception\n(1 of 3)\nTelescoping or invagination of one part of the intestine to another: Cause of obstruction\nMost common scenario: Ileum invaginating into the cecum\nMesentery constricted and obstructing venous return, leading to venous stasis, engorgement, edema, exudation, and further vascular compression\nIf left untreated: Bleeding, necrosis, bowel perforation, and gangrene ensue\n31\nSpeaker notes: \n\nCH42S32\nIntussusception\n(2 of 3)\nClinical manifestations\nAbdominal pain.\nInfants:  Irritable (colicky) and flexes the knees.\nVomiting occurs soon after the pain begins.\n “Currant jelly” stools, which appear dark and gelatinous because of their blood and mucus content.\nTreatment\nEnema reduction\nIf not successful: Surgery\nIf left untreated: Fatal\n32\nSpeaker notes: ",
