   "explain": "The source manages fluid and electrolytes before pyloromyotomy.",
   "decision": "preoperative",
   "evidenceExcerpt": "CH42S14\nInfantile Hypertrophic Pyloric Stenosis\n(3 of 5)\nClinical manifestations\nProjectile vomiting after feeding\nVomiting causes weight loss, fluid and electrolyte imbalances, chronic malnutrition, and dehydration.\nCan be fatal within 4–6 weeks.\n14\nSpeaker notes: \n\nCH42S15\nInfantile Hypertrophic Pyloric Stenosis\n(4 of 5)\nTreatment\nPyloromyotomy: Muscles of the pylorus are split and separated.\nFluid and electrolyte losses are managed before surgical intervention.\nChildren can usually tolerate feeding several hours after surgery.\n15\nSpeaker notes: ",
