   "tier": 1,
   "pool": "mock",
   "explain": "Volvulus is twisting associated with poor fixation.",
   "decision": "malrotation",
   "evidenceExcerpt": "CH42S18\nIntestinal Malrotation\n(1 of 4)\nIleum and cecum normally rotate during the 10th week of embryonic development to enable the cecum to be in the right lower quadrant and fixed to the abdomen by the mesentery.\n18\nSpeaker notes: \n\nCH42S19\nIntestinal Malrotation\n(2 of 4)\nMalrotation \nNormal rotation does not occur.\nPeriduodenal bands (Ladd bands)\nColon remains in the upper right quadrant; an abnormal membrane may press on and obstruct the duodenum. \nMalrotated intestine can easily twist as a result of a poor connection: Twisting is volvulus.\n19\nSpeaker notes: \n\nCH42S20\nIntestinal Malrotation\n(3 of 4)\nClinical manifestations\nBile-stained vomiting is intermittent or persistent after feedings.\nDehydration and electrolyte imbalance occur.\nFever, pain, scanty stools, diarrhea, bloody stools, and severe dehydration are associated with progressive volvulus.\n20\nSpeaker notes: \n\nCH42S21\nIntestinal Malrotation\n(4 of 4)\nTreatment\nReduction of volvulus: Laparoscopic or open Ladd’s surgery\nNecrotic bowel: Resected \nPrimary anastomosis \nEnterostomy\n: May be created\n21\nSpeaker notes: \n\nCH42S17\nObstructions of the Duodenum, Jejunum, and Ileum\nAre caused by intrinsic malformations (atresia or stenosis) or external pressure.\nStenosis (narrowing of the lumen): Causes dilation proximal to the obstruction and luminal collapse distal to the obstruction.\nObstructions \nMay be partial or complete.\nAre usually located at or near the major duodenal papilla.\n17\nSpeaker notes: \n\nCH42S24\nHirschsprung\n \nDiease\nObstruction of colon\nMost common cause of colon obstruction\nFailure of neural crest cells to migrate into GI tract\nSkipped segments\nDelayed passage of meconium, poor feeding, poor weight gain, abdominal distension\nTreatment is surgical.\nOther obstructions\nIdiopathic intestinal pseudo-obstruction (rare)\nDistal intestinal obstruction syndrome\n24\nSpeaker notes: \n\nCH42S31\nIntussusception\n(1 of 3)\nTelescoping or invagination of one part of the intestine to another: Cause of obstruction\nMost common scenario: Ileum invaginating into the cecum\nMesentery constricted and obstructing venous return, leading to venous stasis, engorgement, edema, exudation, and further vascular compression\nIf left untreated: Bleeding, necrosis, bowel perforation, and gangrene ensue\n31\nSpeaker notes: ",
