   "evidenceExcerpt": "CH42S24\nHirschsprung\n \nDiease\nObstruction of colon\nMost common cause of colon obstruction\nFailure of neural crest cells to migrate into GI tract\nSkipped segments\nDelayed passage of meconium, poor feeding, poor weight gain, abdominal distension\nTreatment is surgical.\nOther obstructions\nIdiopathic intestinal pseudo-obstruction (rare)\nDistal intestinal obstruction syndrome\n24\nSpeaker notes: \n\nCH42S12\nInfantile Hypertrophic Pyloric Stenosis\n(1 of 5)\nObstruction of the pyloric sphincter is caused by hypertrophy of the sphincter muscle.\nRisk factors\nIncreased gastrin secretion by the mother in the last trimester \nOverproduction of gastric secretions in the infant that may be caused by stress-related factors in the mother\nExogenous administration of prostaglandin E \nIncreased risk factors if a family member has had pyloric stenosis\n12\nSpeaker notes: \n\nCH42S26\nAnorectal Malformations\nAnal or rectal agenesis, atresia, and fistula\nDeformities that cause complete obstruction\nCalled imperforate anus\nOf infants born with anorectal malformations, 40% have other anomalies.\nDown syndrome, \nHirschsprung\n disease, duodenal atresia, neurogenic bladder, spinal malformations\nTreatment\nAnal stenosis: Dilations\nAll other anorectal malformations: Surgery\n26\nSpeaker notes: \n\nCH42S64\nBiliary Atresia\nRare congenital malformation, characterized by the absence or obstruction of the extrahepatic bile duct\nInflammation, fibrosis, loss of epithelial cells, and obstruction of the bile canaliculi \nPrimary clinical manifestation: Jaundice\nTreatment\nSurgical drainage and correction\nKasai portoenterostomy\nLiver transplantation\n64\nSpeaker notes: ",
