   "explain": "Villous loss removes absorptive surface.",
   "decision": "villous loss",
   "evidenceExcerpt": "CH42S37\nCeliac Disease\n(1 of 6)\nIs an autoimmune disease of the small intestinal villous epithelium when the cereal, protein gluten, is ingested.\nIncidence is 1% worldwide. \nInvolves cellular and humoral immunity.\nCauses T cell-mediated autoimmune injury to the intestinal epithelial cells.\nT-cell infiltration results in mucosal cell destruction with inflammation, atrophy, and flattening of villi in the upper small intestine.\n37\nSpeaker notes: \n\nCH42S38\nCeliac Disease\n(2 of 6)\nGluten: Is the protein component in cereal grains (wheat, rye, barley, oats, malt). \nPerson loses villous epithelium in the intestinal tract; gluten protein acts as a toxin.\nAppears to be caused by environmental, genetic, and immunologic factors. \n38\nSpeaker notes: \n\nCH42S39\nCeliac Disease\n(3 of 6)\nClinical manifestations\nDiarrhea, \nmeconium\n \nileus\n:  Early signs\nStools: Pale, bulky, greasy, foul smelling\nFailure of child to grow and thrive\nMalabsorption symptoms: Rickets, bleeding, anemia, fat-soluble vitamin deficiencies\nDehydration, malabsorption, protein loss\nMagnesium and calcium malabsorption: Irritability, tremor, convulsions, tetany, bone pain, dental abnormalities, \nosteomalacia\n39\nSpeaker notes: \n\nCH42S40\nCeliac Disease\n(4 of 6)\nDermatitis herpetiformis\nItchy blister formation on elbows, knees, shoulders, middle line of back/buttocks\nEvaluation\nSerologic \nantiendomysial\n and \nantitransglutaminase\n IgA antibodies and human leukocyte antigen (HLA)–type DQ2 or DQ8 (HLA class II haplotypes that regulate immunity) confirm the diagnosis.\nDuodenal biopsy detects the classic mucosal changes caused by gluten-sensitive enteropathy and confirms the diagnosis.\n40\nSpeaker notes: \n\nCH42S41\nCeliac Disease\n(5 of 6)\nTreatment\nImmediately and permanently institute a gluten-free diet.\nLactose (milk sugar) intolerance is presumed because of damage to the villi.\nLactose is excluded from the diet; may be reintroduced after healing.\nFat-soluble vitamins, iron, folic acid\n41\nSpeaker notes: ",
