   "evidenceExcerpt": "CH42S41\nCeliac Disease\n(5 of 6)\nTreatment\nImmediately and permanently institute a gluten-free diet.\nLactose (milk sugar) intolerance is presumed because of damage to the villi.\nLactose is excluded from the diet; may be reintroduced after healing.\nFat-soluble vitamins, iron, folic acid\n41\nSpeaker notes: \n\nCH42S58\nPrimary Lactose Intolerance\n(1 of 3)\nInability to digest milk sugar (lactose)\nCause: Inadequate production of lactase, the enzyme that catabolizes lactose\nMalabsorbed lactose: Causes osmotic diarrhea, abdominal pain, bloating, flatulence \n58\nSpeaker notes: \n\nCH40S14\nMouth and Esophagus\n(2 of 7)\nSalivary glands\nThree pairs\nSubmandibular\nSublingual\nParotid\nSaliva\nIs composed of water with mucus, sodium, bicarbonate, chloride, potassium, and salivary \nα\n-amylase (carbohydrate digestion).\nIs controlled by sympathetic (increases) and parasympathetic (decreases) fibers.\nContains immunoglobulin A (IgA).\n14\nSpeaker notes: \n\nCH40S73\nExocrine Pancreas\n(2 of 2)\nEnzymes\nTrypsinogen, \nchymotrypsinogen\n, and \nprocarboxypeptidase\nInactivates proteases\nIs activated by enterokinase\nTrypsin inhibitor\nPrevents the pancreas from eating itself\nEnterokinase\nActivates proenzymes in the duodenum\nPancreatic a-amylase\nDigests carbohydrate\nPancreatic lipase\nDigests fat\n73\nSpeaker notes: ",
