   "evidenceExcerpt": "CH42S34\nCystic Fibrosis\n(1 of 3)\nIs a genetically transmitted disease (dysfunction of the CFTR protein) that involves many organs and systems.\nUsually causes death in childhood or young adulthood.\nDeficiency of pancreatic enzymes in the digestive tract \nResult of overproduction of extremely viscous mucus and pancreatic enzyme deficiency\n34\nSpeaker notes: \n\nCH42S35\nCystic Fibrosis\n(2 of 3)\nClassic triad\nDeficiency of pancreatic enzyme\nOverproduction of mucus in the respiratory tract\nAbnormally elevated sodium and chloride concentrations\nPancreatic insufficiency\nObstruction of pancreatic ducts with thick mucus: Blocks flow of pancreatic enzymes; causes degenerative and fibrotic changes \nPancreatic damage can eventually affect the beta cells, resulting in diabetes mellitus. \n35\nSpeaker notes: ",
