   "evidenceExcerpt": "CH42S25\nDistal Intestinal Obstruction Syndrome\nFormerly called meconium \nileus\n equivalent.\nAssociated with cystic fibrosis.\nIntestinal contents: Abnormally thick; partially or completely impact the colon or intestinal lumen\nImpactions frequently occur after periods of dehydration and the lack of pancreatic enzymes.\nTreatment: Hypertonic enemas\n25\nSpeaker notes: \n\nCH42S9\nEsophageal Malformations\n(1 of 3)\nEsophageal atresia\nEsophagus ends in a blind pouch.\nEndodermal cells exhibit defective growth.\nTracheoesophageal fistula\nIs an abnormal connection between the trachea and the esophagus; various forms exist.\nIs the incomplete fusion of the lateral walls of the foregut, leading to the incomplete closure of the laryngotracheal tube.\n9\nSpeaker notes: \n\nCH42S26\nAnorectal Malformations\nAnal or rectal agenesis, atresia, and fistula\nDeformities that cause complete obstruction\nCalled imperforate anus\nOf infants born with anorectal malformations, 40% have other anomalies.\nDown syndrome, \nHirschsprung\n disease, duodenal atresia, neurogenic bladder, spinal malformations\nTreatment\nAnal stenosis: Dilations\nAll other anorectal malformations: Surgery\n26\nSpeaker notes: \n\nCH42S64\nBiliary Atresia\nRare congenital malformation, characterized by the absence or obstruction of the extrahepatic bile duct\nInflammation, fibrosis, loss of epithelial cells, and obstruction of the bile canaliculi \nPrimary clinical manifestation: Jaundice\nTreatment\nSurgical drainage and correction\nKasai portoenterostomy\nLiver transplantation\n64\nSpeaker notes: ",
