   "evidenceExcerpt": "CH42S55\nAcute Infectious Diarrhea\n(1 of 3)\nIncrease in the water content, volume, or frequency of stools \nAcute vs. chronic\nProlonged diarrhea: Very dangerous \nChildren have lower fluid reserves than adults.\nCauses: osmotic, secretory, intestinal, \ndysmotility\n, inflammatory\n55\nSpeaker notes: \n\nCH42S56\nAcute Infectious Diarrhea\n(2 of 3)\nInfant diarrhea\nDanger of dehydration is great.\nInfectious diarrhea\nIs associated with acute viral or bacterial gastroenteritis.\nContaminated food, water\nRotavirus\nIs the leading cause of severe diarrhea in infants and young children worldwide.\nChronic diarrhea\nLasts longer than 2 weeks.\n56\nSpeaker notes: \n\nCH42S57\nAcute Infectious Diarrhea\n(3 of 3)\nTreatment\nRehydration with fluids and electrolytes\nMaintenance of nutrition\nTreatment of associated conditions\nAntibiotics, antispasmodics, probiotics\nIV solutions\nPrevention\nClean water\nGood hygiene\nEnvironmental sanitation\nVaccines\n57\nSpeaker notes: ",
