   "evidenceExcerpt": "CH42S28\nGastroesophageal Reflux (GER)\n and Gastroesophageal Reflux Disease (GERD)\n(1 of 3)\nReturn of stomach contents into the esophagus from relaxation or incompetence of the lower esophageal sphincter\nIn newborns: Reflux is normal.\nNeuromuscular control of the gastroesophageal sphincter is not fully developed.\nInfants usually outgrow this condition.\nCause: Ineffective protective mechanisms \nPersistent reflux: Mucosal erosion, bleeding, dysphagia, or failure to thrive\n28\nSpeaker notes: ",
