   "explain": "The supplied NEC mechanism includes ischemia and immature barrier.",
   "decision": "necrotizing",
   "evidenceExcerpt": "CH42S51\nNecrotizing Enterocolitis\n(1 of 4)\nIs an ischemic, inflammatory condition that causes bowel necrosis and perforation.\nCauses infant death, if left untreated.\nIs the most common gastrointestinal emergency of the newborn. \nIs thought to be from reduced mucosal blood flow and immature mucosal barrier.\nIschemia leads to inflammation and necrosis of the intestinal segments and possible perforation.\nBacteria invade the mucosa.\n51\nSpeaker notes: \n\nCH42S52\nNecrotizing Enterocolitis\n(2 of 4)\nContributing factors\nInfections, abnormal bacterial colonization, intestinal ischemia, immature immune responses, exaggerated inflammatory responses, immature intestinal motility, altered microcirculatory blood flow and barrier function, perinatal stress, effects of medications and feeding practices, and genetic predisposition \n52\nSpeaker notes: \n\nCH42S53\nNecrotizing Enterocolitis\n(3 of 4)\nClinical manifestations\nFeeding intolerance, abdominal distention and bloody stools after 8–10 days of age, septicemia with elevated white blood cell count, falling platelet levels, unstable temperature, bradycardia, apnea\n53\nSpeaker notes: \n\nCH42S54\nNecrotizing Enterocolitis\n(4 of 4)\nTreatment\nCessation of feeding formula milk\nGastric suction: To decompress the intestines\nMaintenance of fluid and electrolytes\nAdministration of antibiotics: To control sepsis\nSurgical resection\n54\nSpeaker notes: ",
