   "tier": 1,
   "pool": "practice",
   "explain": "Fibrosis increases resistance within hepatic sinusoids.",
   "decision": "location",
   "evidenceExcerpt": "CH42S70\nPortal Hypertension\n(1 of 4)\nCauses\nIncreased resistance to blood flow within the portal system\nIncreased volume of portal blood flow\nExtrahepatic portal hypertension\nMain cause: Obstruction of the portal vein\nTreatment\nMesoportal\n bypass\n70\nSpeaker notes: \n\nCH42S71\nPortal Hypertension\n(2 of 4)\nIntrahepatic portal hypertension\nMost common causes: Cirrhosis and congenital hepatic fibrosis\nClinical manifestations\nSplenomegaly\nUpper gastrointestinal bleeding\nAscites\nHepatopulmonary\n syndrome\nHepatorenal\n syndrome\nHepatic encephalopathy\n71\nSpeaker notes: \n\nCH42S72\nPortal Hypertension\n(3 of 4)\nTreatment\nSame as in adults\n72\nSpeaker notes: \n\nCH42S73\nPortal Hypertension\n(4 of 4)\nQuestion 5\nIntrahepatic portal hypertension is associated with:\numbilical vein catheterization.\nobstruction of the portal vein.\ncirrhosis.\npancreatitis.\n73\nSpeaker notes: Elsevier items and derived items © 2009, 2005, 2001 by Saunders, an imprint of Elsevier Inc.\n73\nANS:\n 3\nCirrhosis is the most common cause of intrahepatic portal hypertension in children. Fibrosis increases resistance to portal blood flow by constricting and reducing the compliance of the hepatic sinusoids. \n1. Umbilical vein catheterization is a risk factor for extrahepatic portal hypertension. \n2. Obstruction of the portal vein is the most common cause\n of \nextrahepatic portal hypertension.\n4. Pancreatitis can produce extrahepatic portal hypertension.",
   "editorialRevision": "u6-dna-2026-10-01-r1",
