   "evidenceExcerpt": "CH42S69\nCirrhosis\nFibrotic scarring of the liver occurs in response to inflammation and tissue damage.\nChronic liver diseases in children can progress to cirrhosis, although infrequently.\nComplications for cirrhosis in children are the same as those in adults.\nChildren may also experience growth failure, nutritional deficits, and developmental delays.\n69\nSpeaker notes: ",
