   "tier": 1,
   "pool": "mock",
   "explain": "Absence or obstruction of extrahepatic ducts defines biliary atresia.",
   "decision": "bile atresia",
   "evidenceExcerpt": "CH42S61\nNeonatal Jaundice\n(1 of 3)\nBenign, transient icterus that occurs during the first week of life in an otherwise healthy, full-term infant\nMild unconjugated hyperbilirubinemia\nPathologic jaundice: Appearing within \n24 hours after birth\nKernicterus\nChronic bilirubin encephalopathy\nDeposition of toxic, unconjugated bilirubin in the brain \n61\nSpeaker notes: \n\nCH42S62\nNeonatal Jaundice\n(2 of 3)\nClinical manifestations\nYellowing skin, dark urine, light-colored stools, weight loss\nEvaluation\nSerum bilirubin values that increase greater than 5 mg/\ndL\n per day, persistent jaundice (more than 7—10 days in the full-term infant), or conjugated bilirubin values greater than 2 mg/\ndL\n. Other causes of jaundice must be eliminated to confirm physiologic jaundice.\n62\nSpeaker notes: \n\nCH42S63\nNeonatal Jaundice\n(3 of 3)\nTreatment\nPhysiologic jaundice\nPhototherapy (ultraviolet light) with eye protection\nProduces isomers of bilirubin, which are water soluble, can be more rapidly excreted in the stools and urine, and do not cross the blood-brain barrier.\nPathologic jaundice\nHigh-intensity phototherapy, exchange transfusion, and treatment of the underlying cause\n63\nSpeaker notes: \n\nCH42S64\nBiliary Atresia\nRare congenital malformation, characterized by the absence or obstruction of the extrahepatic bile duct\nInflammation, fibrosis, loss of epithelial cells, and obstruction of the bile canaliculi \nPrimary clinical manifestation: Jaundice\nTreatment\nSurgical drainage and correction\nKasai portoenterostomy\nLiver transplantation\n64\nSpeaker notes: \n\nCH42S65\nHepatitis\n(1 of 4)\nHepatitis A virus (HAV)\nOne-third to one-half of cases occur in children.\nHAV replicates in the liver and is excreted through\nthe biliary system into the stool.\nVaccines should begin at 1 year.\n65\nSpeaker notes: \n\nCH42S66\nHepatitis\n(2 of 4)\nHepatitis B\nNewborns infected with hepatitis B from their mothers develop chronic hepatitis and become carriers.\nAggressive vaccination programs have reduced the incidence rate.\nTreatment option: Maternal antiviral therapy during pregnancy and lactation \n66\nSpeaker notes: \n\nCH42S67\nHepatitis\n(3 of 4)\nHepatitis C\nIs primarily associated with blood transfusions and maternal HIV.\nAntivirals: Are effective in the treatment of hepatitis C.\nLiver transplantation:  Required for those with liver failure.\nCurrently, no vaccination is available. \n67\nSpeaker notes: \n\nCH42S68\nHepatitis\n(4 of 4)\nChronic hepatitis\nMain causes: Hepatitis B and C.\nManifestations:  Malaise, anorexia, fever, gastrointestinal bleeding, hepatomegaly, edema, and transient joint pain.\nNo curative therapy is available.\nLiver transplantation may be needed.\n68\nSpeaker notes: \n\nCH42S69\nCirrhosis\nFibrotic scarring of the liver occurs in response to inflammation and tissue damage.\nChronic liver diseases in children can progress to cirrhosis, although infrequently.\nComplications for cirrhosis in children are the same as those in adults.\nChildren may also experience growth failure, nutritional deficits, and developmental delays.\n69\nSpeaker notes: ",
