   "evidenceExcerpt": "CH42S61\nNeonatal Jaundice\n(1 of 3)\nBenign, transient icterus that occurs during the first week of life in an otherwise healthy, full-term infant\nMild unconjugated hyperbilirubinemia\nPathologic jaundice: Appearing within \n24 hours after birth\nKernicterus\nChronic bilirubin encephalopathy\nDeposition of toxic, unconjugated bilirubin in the brain \n61\nSpeaker notes: \n\nCH41S56\nMalabsorption Syndromes\n(2 of 5)\nPancreatic insufficiency\nInsufficient pancreatic enzyme production\nLipase, amylase, trypsin, or chymotrypsin\nCauses: Pancreatitis, pancreatic carcinoma, pancreatic resection, and cystic fibrosis\nFat maldigestion: Primary problem\nMost common signs: Fatty stools (steatorrhea); weight loss\nTreatment: Lipase supplements\n56\nSpeaker notes: \n\nCH41S83\nAscites\n(3 of 5)\nAccumulation of fluid in the peritoneal cavity\nMost common cause: Cirrhosis\nClinical manifestations\nAbdominal distention, increased abdominal girth, and weight gain\nEvaluation\nSerum-ascites albumin gradient (SAAG): Most specific diagnostic indicator\n83\nSpeaker notes: \n\nCH41S86\nHepatic Encephalopathy\n(1 of 2)\nComplex neurological syndrome characterized by impaired behavioral, cognitive, and motor function\nClinical manifestations\nPersonality changes\nConfusion\nIrritability\nLethargy\nSleep disturbances\nFlapping tremor (asterixis)\nStupor, coma, death\n86\nSpeaker notes: ",
