   "evidenceExcerpt": "CH43S12\nBone Cells\n(1 of 5)\nOsteoblasts: Bone forming\nAre derived from mesenchymal cells.\nProduce osteocalcin.\nForm new bone.\nSynthesize osteoid.\nNonmineralized bone matrix\nBone is shaped according to its function.\nBecome osteocytes that are imbedded in bone.\n12\nSpeaker notes: \n\nCH43S13\nBone Cells\n(2 of 5)\nOsteocytes: Bone maintenance\nDevelop dendritic processes that extend to either the bone surface or the bone’s vascular space.\nHelp maintain bone by signaling osteoblasts and osteoclasts to form and resorb bone.\nAre located in the lacuna.\nCoordinate osteoblast and osteoclast functions.\nRespond to parathyroid hormone.\n13\nSpeaker notes: \n\nCH43S14\nBone Cells\n(3 of 5)\nOsteoclasts: Bone resorption\nAre large, multinucleated cells.\nContain lysosomes filled with hydrolytic enzymes.\nHave microvilli called ruffled borders.\nAre located in Howship lacunae.\nAre attached to integrins by \npodosomes\n (helps bind to bone)\nOsteoclasts loosen from bone surface.\nOsteoclasts become inactive and rest.\n14\nSpeaker notes: \n\nCH43S15\nBone Cells\n(4 of 5)\nReceptor activator of nuclear factor kappa B (\nκ\nB) ligand (\nRANKL)\nInduces osteoclast activation and bone resorption.\nOsteoprotegerin (\nOPG)\nIs a glycoprotein.\nCoupling of osteoblasts and osteoclasts.\nServes as a decoy receptor for RANKL, and blocks osteoclast activity (decreasing bone resorption).\nBalance between RANKL and OPG determines the quality of bone.\n15\nSpeaker notes: ",
