   "evidenceExcerpt": "CH43S12\nBone Cells\n(1 of 5)\nOsteoblasts: Bone forming\nAre derived from mesenchymal cells.\nProduce osteocalcin.\nForm new bone.\nSynthesize osteoid.\nNonmineralized bone matrix\nBone is shaped according to its function.\nBecome osteocytes that are imbedded in bone.\n12\nSpeaker notes: \n\nCH43S13\nBone Cells\n(2 of 5)\nOsteocytes: Bone maintenance\nDevelop dendritic processes that extend to either the bone surface or the bone’s vascular space.\nHelp maintain bone by signaling osteoblasts and osteoclasts to form and resorb bone.\nAre located in the lacuna.\nCoordinate osteoblast and osteoclast functions.\nRespond to parathyroid hormone.\n13\nSpeaker notes: \n\nCH43S14\nBone Cells\n(3 of 5)\nOsteoclasts: Bone resorption\nAre large, multinucleated cells.\nContain lysosomes filled with hydrolytic enzymes.\nHave microvilli called ruffled borders.\nAre located in Howship lacunae.\nAre attached to integrins by \npodosomes\n (helps bind to bone)\nOsteoclasts loosen from bone surface.\nOsteoclasts become inactive and rest.\n14\nSpeaker notes: \n\nCH43S36\nSynovial Joints\n(4 of 6)\nArticular cartilage\nHyaline cartilage covers the end of each bone.\nReduces friction in the joint, and distributes forces of \nweightbearing\n.\nIs composed of chondrocytes (cartilage cells) and an intercellular matrix (collagen, polysaccharides and mostly water).\nIs layered.\nDense protective mat on surface\nTangentially arranged fibers in middle zone for \nweightbearing\nOn bottom layer, perpendicular fibers resist shear forces, and a calcified layer (tidemark) anchors them to bone\nHas no blood vessels, lymph vessels, or nerves.\nIs insensitive to pain, and regenerates slowly after injury.\n36\nSpeaker notes: ",
