   "evidenceExcerpt": "CH43S9\nElements of Bone Tissue\n(1 of 3)\nRigid yet flexible connective tissue\nConstituents\nCells\nEnable bone to grow, repair itself, change shape, synthesize new bone tissue, and resorb old bone tissue.\nFibers: Collagen\nGives bone its tensile strength—ability to hold itself together.\nGround substance: Gelatinous material\nIs the medium for diffusion between bone and blood vessels.\nCrystallized minerals: Especially calcium\nProvides rigidity.\n9\nSpeaker notes: \n\nCH43S18\nBone Matrix\n(2 of 4)\nCollagen fibers\nAre essential for bone strength.\nForm fibrils that twist. \nAre synthesized and secreted by osteoblasts.\nHave over 20 types: All their functions are not yet known.\n18\nSpeaker notes: ",
