   "evidenceExcerpt": "CH43S21\nBone Minerals\nBone formation\nFirst step: Develop bone matrix \nFinal step: Calcification or mineralization\nMineralization\nFinal step in bone formation\nPhases\nFormation of the initial mineral deposit (initiation)\nProliferation or accretion of additional mineral crystals on the initial mineral deposits (growth)\nMajority of the mineral content in the body: Hydroxyapatite—the end product of mineralization\n21\nSpeaker notes: ",
