   "evidenceExcerpt": "CH43S25\nCharacteristics of Bone\n(2 of 3)\nLong bones\nDiaphysis\nMedullary cavity contains fat: Yellow marrow\nMetaphysis\nBroad neck\nEpiphysis\nEpiphyseal plate\nIn a child, epiphysis is separated from metaphysis by a cartilaginous growth plate; after puberty, the epiphyseal plate calcifies and the epiphysis and metaphysis merge. \nMedullary cavity helps with blood formation: Red marrow\nEndosteum: Lines medullary cavities\n25\nSpeaker notes: \n\nCH45S8\nBone Growth\n(1 of 2)\nUntil adult stature is achieved, bone growth occurs at the \nphyseal\n plate through endochondral ossification.\nBone is being constantly destroyed and re-formed. \nEpiphyseal closure\nUnites the metaphysis and the epiphysis.\nOccurs earlier in girls than in boys because of earlier puberty in girls.\n8\nSpeaker notes: ",
