   "evidenceExcerpt": "CH43S34\nSynovial Joints\n(2 of 6)\nJoint capsule\nConnective tissue covers the ends of the bones where they meet in the joint.\nIs richly supplied with nerves, blood vessels, and lymphatic vessels.\nSynovial membrane\nIs a smooth, delicate inner lining of the joint capsule.\nHas a vascular layer (subintima) and a thin cellular layer (intima).\nType A synovial cells: Perform phagocytosis.\nType B synovial cells: Secrete hyaluronate.\n34\nSpeaker notes: \n\nCH43S36\nSynovial Joints\n(4 of 6)\nArticular cartilage\nHyaline cartilage covers the end of each bone.\nReduces friction in the joint, and distributes forces of \nweightbearing\n.\nIs composed of chondrocytes (cartilage cells) and an intercellular matrix (collagen, polysaccharides and mostly water).\nIs layered.\nDense protective mat on surface\nTangentially arranged fibers in middle zone for \nweightbearing\nOn bottom layer, perpendicular fibers resist shear forces, and a calcified layer (tidemark) anchors them to bone\nHas no blood vessels, lymph vessels, or nerves.\nIs insensitive to pain, and regenerates slowly after injury.\n36\nSpeaker notes: \n\nCH43S11\nElements of Bone Tissue\n(3 of 3)\nTransforming growth factor–beta (TGF-β) family\nIs responsible for initiating, differentiating, and committing precursor cells into osteoblasts.\nWnt genes \nProtein-signaling factors are required for the development of body systems, including the musculoskeletal system. \nAre responsible for bone formation, bone mass development, remodeling, and fracture healing.\n11\nSpeaker notes: ",
