   "evidenceExcerpt": "CH43S34\nSynovial Joints\n(2 of 6)\nJoint capsule\nConnective tissue covers the ends of the bones where they meet in the joint.\nIs richly supplied with nerves, blood vessels, and lymphatic vessels.\nSynovial membrane\nIs a smooth, delicate inner lining of the joint capsule.\nHas a vascular layer (subintima) and a thin cellular layer (intima).\nType A synovial cells: Perform phagocytosis.\nType B synovial cells: Secrete hyaluronate.\n34\nSpeaker notes: \n\nCH43S35\nSynovial Joints\n(3 of 6)\nJoint cavity\nIs called the joint space.\nEnables two bones to move “against” one another.\nIs filled with synovial fluid.\nSynovial fluid\nSuperfiltrated\n plasma fluid.\nLubricates the joint surfaces and nourishes the pad of the articular cartilage. \nContains free-floating synovial cells and various leukocytes that phagocytize joint debris and microorganisms.\n35\nSpeaker notes: ",
