   "evidenceExcerpt": "CH43S32\nCartilaginous Joints\nAre connected by fibrocartilage or hyaline cartilage.\nSymphysis\nBones are united by a pad or disk of fibrocartilage. \nExamples: \nSymphysis\n pubis and intervertebral disks.\nSynchondrosis\nBones are united by hyaline cartilage (costal cartilage). \nExamples: Joints between the ribs and the sternum.\n32\nSpeaker notes: \n\nCH43S31\nFibrous Joints\nAre directly united to bone by dense fibrous connective tissue.\nAre usually synarthroses (immovable).\nHowever, many fibrous joints allow some movement.\nDegree of movement depends on the distance between the bones and the flexibility of the fibrous connective tissue.\nExamples: Sutures, syndesmoses, and gomphoses. \n31\nSpeaker notes: \n\nCH43S33\nSynovial Joints\n(1 of 6)\nMost movable, most complex, diarthrosis \nFibrous joint capsule: \nArticular\n capsule\nSynovial membrane: Lines the inner surface of the joint capsule.\nJoint cavity (synovial cavity): Space formed by the capsule.\nSynovial fluid: Fills the joint cavity and lubricates the joint surface.\nArticular cartilage: Covers and pads the articulating bony surfaces.\n33\nSpeaker notes: ",
