   "evidenceExcerpt": "CH43S35\nSynovial Joints\n(3 of 6)\nJoint cavity\nIs called the joint space.\nEnables two bones to move “against” one another.\nIs filled with synovial fluid.\nSynovial fluid\nSuperfiltrated\n plasma fluid.\nLubricates the joint surfaces and nourishes the pad of the articular cartilage. \nContains free-floating synovial cells and various leukocytes that phagocytize joint debris and microorganisms.\n35\nSpeaker notes: \n\nCH43S36\nSynovial Joints\n(4 of 6)\nArticular cartilage\nHyaline cartilage covers the end of each bone.\nReduces friction in the joint, and distributes forces of \nweightbearing\n.\nIs composed of chondrocytes (cartilage cells) and an intercellular matrix (collagen, polysaccharides and mostly water).\nIs layered.\nDense protective mat on surface\nTangentially arranged fibers in middle zone for \nweightbearing\nOn bottom layer, perpendicular fibers resist shear forces, and a calcified layer (tidemark) anchors them to bone\nHas no blood vessels, lymph vessels, or nerves.\nIs insensitive to pain, and regenerates slowly after injury.\n36\nSpeaker notes: ",
