   "decision": "calcium return",
   "evidenceExcerpt": "CH43S53\nMuscle Contraction at the Molecular Level\n(1 of 3) \nFunction of muscle: To accomplish work\nRyanodine receptors (RyRs): Primary ion channels that control calcium release in muscles\nRyR1: Skeletal muscle\nRyR2: Cardiac muscle\nRyR3: Diaphragm, smooth muscle, and brain\nPhases\nExcitation, coupling, contraction, relaxation\n53\nSpeaker notes: \n\nCH43S54\nMuscle Contraction at the Molecular Level\n(2 of 3) \nExcitation\nIs the spread of action potential from the nerve terminal to the neuromuscular junction.\nInitiates an electrical impulse; muscle fiber action potential.\nTriggers voltage-sensitive receptors in the t-tubule wall, opening RyR channels and releasing calcium.\nCoupling\nRelease of calcium leaves actin free to bind with myosin.\n54\nSpeaker notes: \n\nCH43S55\nMuscle Contraction at the Molecular Level\n(3 of 3) \nContraction\nThin filament, actin, then slides toward the thick filament, myosin, forming a cross-bridge that causes muscle to shorten (sliding-filament theory, now called the cross-bridge theory).\n“All or nothing” principle applies.\nRelaxation\nCross-bridge detaches, and a sarcomere lengthens as calcium is pumped back into the sarcoplasmic reticulum.\n55\nSpeaker notes: ",
