   "evidenceExcerpt": "CH43S56\nMuscle Metabolism\nRequires a constant supply of adenosine triphosphate (ATP) and phosphocreatine.\nFuels complex processes of muscle contraction.\nDrives the cross-bridges of actin and myosin.\nTransports calcium from the sarcoplasmic reticulum to the myofibril.\nDuring activity: Need for ATP increases 100-fold.\nOxygen debt: Is the amount of oxygen needed to convert the buildup of lactic acid to glucose and replenish ATP and phosphocreatine stores.\n56\nSpeaker notes: \n\nCH43S49\nWhole Muscle\n(7 of 7)\nQuestion 4\nA person has a problem with a muscle that has a low innervation ratio. Which problem will this person have? \nImpaired myogenesis \nLack of endurance\nEasily fatigued\nInadequate precision movement \n \n49\nSpeaker notes: Elsevier items and derived items © 2009, 2005, 2001 by Saunders, an imprint of Elsevier Inc.\n49\nANS: \n4\nHigher innervation ratios prevent fatigue, and lower innervation ratios allow for precision of movement.\n \n1. \nA critical component of successful embryonic muscle formation (myogenesis) is protein kinase, not a low innervation ratio.\n \n2. \nThe greater the innervation ratio of a particular organ, the greater is its endurance.\n \n3. \nHigher innervation ratios prevent fatigue, and lower innervation ratios allow for precision of movement.\n\nCH43S50\nMuscle Fibers\n(1 of 3)\nEach muscle fiber is a single muscle cell\nSurrounded by a membrane capable of excitation and impulse propagation\nMyofibrils\nFunctional units of contractions\nWhite muscle (type II fibers): Fast\nRed muscle (type I fibers): Slow\nMuscle membrane\nSarcolemma: Propagates impulse\nBasement membrane: Maintains cell’s shape\n50\nSpeaker notes: ",
