   "evidenceExcerpt": "CH43S58\nTypes of Muscle Contraction\nIsometric\nStatic or holding contraction\nMuscle maintains a constant length as tension is increased\nMuscle contracts, but the limb does not move\nDynamic\nLengthening (eccentric) or shortening (concentric) contraction\nMuscle maintains a constant tension as it moves\nMuscle contracts and the limb moves\n58\nSpeaker notes: \n\nCH43S55\nMuscle Contraction at the Molecular Level\n(3 of 3) \nContraction\nThin filament, actin, then slides toward the thick filament, myosin, forming a cross-bridge that causes muscle to shorten (sliding-filament theory, now called the cross-bridge theory).\n“All or nothing” principle applies.\nRelaxation\nCross-bridge detaches, and a sarcomere lengthens as calcium is pumped back into the sarcoplasmic reticulum.\n55\nSpeaker notes: ",
