   "evidenceExcerpt": "CH43S46\nWhole Muscle\n(4 of 7)\nMotor unit: Anterior horn cell, its axon, and its muscle fiber\nAxons of motor nerves branch out to innervate a specific group of muscle fibers.\nIs composed of lower motor neurons.\nIs the functional unit of the neuromuscular system.\nBehaves as a single entity, and contracts as a whole when it receives an electrical impulse.\n46\nSpeaker notes: \n\nCH43S57\nMuscle Mechanics\nWhen a motor unit responds to a single nerve stimulus, a phasic (twitch) contraction develops. \nCentral nervous system smoothly grades the force generated by \n“\nrecruiting\n”\n additional motor units, varying the discharge frequency of each active motor unit.\nAdding motor units within the muscle is a repetitive discharge.\nTetanus: No further increase in force can be achieved.\n57\nSpeaker notes: \n\nCH43S55\nMuscle Contraction at the Molecular Level\n(3 of 3) \nContraction\nThin filament, actin, then slides toward the thick filament, myosin, forming a cross-bridge that causes muscle to shorten (sliding-filament theory, now called the cross-bridge theory).\n“All or nothing” principle applies.\nRelaxation\nCross-bridge detaches, and a sarcomere lengthens as calcium is pumped back into the sarcoplasmic reticulum.\n55\nSpeaker notes: ",
