   "evidenceExcerpt": "CH44S16\nFractures\n(5 of 6)\nImproper reduction or immobilization\nNonunion\nIs the failure of the bone ends to grow together. \nGap between the broken ends of the bone fills with dense fibrous and fibrocartilaginous tissue. \nOccasionally, fibrous tissue contains a fluid-filled space that resembles a joint: Referred to as a false joint or a pseudarthrosis.\nDelayed union\nDoes not occur until approximately 8–9 months after a fracture. \nMalunion\nIs healing of the bone in a nonanatomic position.\n16\nSpeaker notes: \n\nCH43S28\nMaintenance of Bone Integrity\n(2 of 3)\nRepair: Bone heals itself\nHematoma formation\nClot forms.\nProcallus formation\nProduces granulation tissue.\nCallus formation\nForms membranous or woven bone.\nCallus replacement\nReplaces the callus with lamellar bone or trabecular bone.\nRemodeling\nPeriosteal and endosteal surfaces are remodeled to the size and shape of the bone before the injury.\n28\nSpeaker notes: ",
