   "evidenceExcerpt": "CH44S18\nDislocation and Subluxation\nDislocation\nTemporary displacement of bone from its joint\nSubluxation\nContact between the bones in the joint only partially lost\nAssociated with fractures, muscle imbalance, rheumatoid arthritis, other joint instability\n18\nSpeaker notes: \n\nCH44S9\nMusculoskeletal Injuries\n(2 of 4)\nFractur classifications\nComplete: Bone is broken all the way through.\nIncomplete: Bone is damaged but still in one piece.\nClosed or simple (complete or incomplete): Skin is intact.\nOpen or compound (complete or incomplete): Skin is broken.\nComminuted\nBone breaks into more than two fragments. \nLinear\nFracture runs parallel to the long axis of the bone.\nOblique\nFracture of the shaft of the bone is slanted.\n9\nSpeaker notes: \n\nCH44S16\nFractures\n(5 of 6)\nImproper reduction or immobilization\nNonunion\nIs the failure of the bone ends to grow together. \nGap between the broken ends of the bone fills with dense fibrous and fibrocartilaginous tissue. \nOccasionally, fibrous tissue contains a fluid-filled space that resembles a joint: Referred to as a false joint or a pseudarthrosis.\nDelayed union\nDoes not occur until approximately 8–9 months after a fracture. \nMalunion\nIs healing of the bone in a nonanatomic position.\n16\nSpeaker notes: ",
