   "evidenceExcerpt": "CH44S31\nOsteoporosis\n(2 of 6) \nPotential causes\nDecreased levels of estrogen and testosterone\nDecreased activity level\nInadequate levels of vitamins D and calcium or magnesium\nAlterations in the osteoprotegerin (OPG), receptor activator of nuclear factor kappa B (\nκ\nB) ligand (\nRANKL), and \nreceptor activator of nuclear factor \nκ\nB (RANK): OPG/RANKL/RANK system\n31\nSpeaker notes: \n\nCH44S32\nOsteoporosis\n(3 of 6) \nPotential causes (cont.)\nPostmenopausal osteoporosis\nIncreased osteoclast activity, changes in OPG, insulin-like growth factor (IGF), and family history\nOS/ROS\nGlucocorticoids\nIncrease RANKL expression and inhibit OPG production by osteoblasts, leading to lower bone density\n32\nSpeaker notes: \n\nCH44S33\nOsteoporosis\n(4 of 6) \nReduced bone mass or density and an imbalance of bone resorption and formation\nBone histologic anatomy: Usually normal but lacks structural integrity \n33\nSpeaker notes: ",
