   "evidenceExcerpt": "CH44S33\nOsteoporosis\n(4 of 6) \nReduced bone mass or density and an imbalance of bone resorption and formation\nBone histologic anatomy: Usually normal but lacks structural integrity \n33\nSpeaker notes: \n\nCH44S36\nOsteomalacia\n(1 of 2) \nDeficiency of vitamin D lowers the absorption of calcium from the intestines.\nMineralization is inadequate or delayed.\nBone formation progresses to osteoid formation, but calcification does not occur; result is soft bones.\nClinical manifestations:  Pain, bone fractures, vertebral collapse, bone malformation, waddling gait, facial deformities, knock knees\n36\nSpeaker notes: \n\nCH44S38\nPaget Disease\nAlso called osteitis deformans\nState of increased metabolic activity in bone \nIs abnormal, and bone resorption and formation are excessive. \nEnlarges and softens the affected bones.\nMost often affects the axial skeleton.\nClinical manifestations\nSymmetric skull, impaired motor function, deafness, atrophy of the optic nerve, obstruction of lacrimal duct \nTreatment\nBisphosphonates and calcitonin\n38\nSpeaker notes: \n\nCH44S39\nInfectious Bone Disease: Osteomyelitis\n(1 of 3)\nIs usually caused by a \nStaphylococcus aureus\n infection.\nIs often outside the body (exogenous); can be from a bloodborne (endogenous) infection.\nInfection spreads under the periosteum and along the bone shaft or into the bone marrow.\nIn adults: Affects the cortex \nSequestra: Sections of dead bone from periosteal separation\nInvolucrum: Periosteal new bone\nAcute vs. \nsubacute\n vs. chronic\n39\nSpeaker notes: ",
