   "explain": "OA combines cartilage loss and osteophytes.",
   "decision": "cartilage v synovium",
   "evidenceExcerpt": "CH44S49\nOsteoarthritis\n(1 of 4)\nCommon age-related disorder of synovial joints\nInflammatory joint disease\nLoss of articular cartilage, sclerosis of underlying bone, and formation of bone spurs (osteophytes)\nAlso called degenerative joint disease.\nIncidence increases with age.\n49\nSpeaker notes: \n\nCH44S50\nOsteoarthritis\n(2 of 4)\nLocal areas of damage and loss of articular cartilage, new bone formation of joint margins, and thickening of joint capsule\nClinical manifestations\nPain, stiffness, enlargement of the joint, tenderness, limited motion, and deformity\nJoint swelling in the fingers: Heberden and Bouchard nodes\nJoint effusion: Exudate or blood entering the joint\n50\nSpeaker notes: \n\nCH44S51\nOsteoarthritis\n(3 of 4)\nTreatment\nRest of involved joint until inflammation subsides\nAerobic exercise and range-of-motion exercise\nCane, braces, walker\nWeight loss, if obese \nBalanced diet\nAnalgesic and antiinflammatory drug \nMagnetic bracelets and acupuncture\nIntraarticular injection of high-molecular-weight viscosupplements, particularly hyaluronic acid\nSurgery: Joint replacement\n51\nSpeaker notes: \n\nCH44S52\nOsteoarthritis\n(4 of 4)\nQuestion 3\nThe primary defect in osteoarthritis is:\nenlargement and softening of bones.\ndevelopment of \npannus\n.\nloss of articular cartilage.\npermeative\n pattern of bone destruction.\n52\nSpeaker notes: Elsevier items and derived items © 2009, 2005, 2001 by Saunders, an imprint of Elsevier Inc.\n52\nANS: 3\nOsteoarthritis \nis characterized by local areas of loss and damage of articular cartilage, new bone formation of joint margins (osteophytosis), subchondral bone changes, variable degrees of mild synovitis and thickening of the joint capsule\n. \nThe primary defect in OA is loss of articular cartilage.\n1. In Paget disease, c\nhronic accelerated remodeling eventually enlarges and softens the affected bones. \n2. In Rheumatoid arthritis \nT cells also interact with synovial fibroblasts (synoviocytes) through TNF-α, converting synovium into a thick, abnormal layer of granulation tissue known as \npannus\n. \n4. \nThree patterns of bone destruction by bone tumors have been identified: (1) the geographic pattern, (2) the moth-eaten pattern, and (3) the \npermeative\n pattern\n. \n\nCH44S53\nInflammatory Joint Disease\nCommonly called arthritis.\nInflammatory damage or destruction in the synovial membrane or articular cartilage\nSystemic signs of inflammation\nFever, leukocytosis, malaise, anorexia, and hyperfibrinogenemia\nInfectious or noninfectious\n53\nSpeaker notes: \n\nCH44S54\nRheumatoid Arthritis\n(1 of 5)\nRheumatoid arthritis (RA): Inflammatory joint disease\nSystemic autoimmune destruction to synovial membrane and joints\nPresence of rheumatoid factors (RFs): RA or RF test\nAntibodies (immunoglobulin G [IgG] and IgM) against antibodies; sometimes IgA\nJoint fluid with inflammatory exudate\nRupture of cyst or synovial joint\n54\nSpeaker notes: \n\nCH44S55\nRheumatoid Arthritis\n(2 of 5)\nClinical manifestations\nSymmetric joint swelling, joint deformities\nSystemic manifestations of inflammation\nRheumatoid nodules in organs\nCaplan syndrome\nPainful, tender, stiff joints\n55\nSpeaker notes: \n\nCH44S59\nAnkylosing Spondylitis\n(1 of 3)\nChronic inflammatory joint disease of the spine or sacroiliac joints, causing stiffening and fusion of the joints\nUnknown cause but strong association with human leukocyte antigen B27 (\nHLA-B27\n)\nAffects peripheral joints of \nappendicular\n skeleton.\n59\nSpeaker notes: \n\nCH44S62\nGout\n(1 of 6)\nIs a metabolic disorder that disrupts the body’s control of uric acid production or excretion.\nExhibits high levels of uric acid in the blood and other body fluids.\nOccurs when the uric acid concentration increases to high enough levels to crystallize. \nCrystals deposit in connective tissues throughout the body.\nIf prolonged in joints: Gouty arthritis\nTophi: Small, white visible nodules\n62\nSpeaker notes: ",
