   "evidenceExcerpt": "CH44S52\nOsteoarthritis\n(4 of 4)\nQuestion 3\nThe primary defect in osteoarthritis is:\nenlargement and softening of bones.\ndevelopment of \npannus\n.\nloss of articular cartilage.\npermeative\n pattern of bone destruction.\n52\nSpeaker notes: Elsevier items and derived items © 2009, 2005, 2001 by Saunders, an imprint of Elsevier Inc.\n52\nANS: 3\nOsteoarthritis \nis characterized by local areas of loss and damage of articular cartilage, new bone formation of joint margins (osteophytosis), subchondral bone changes, variable degrees of mild synovitis and thickening of the joint capsule\n. \nThe primary defect in OA is loss of articular cartilage.\n1. In Paget disease, c\nhronic accelerated remodeling eventually enlarges and softens the affected bones. \n2. In Rheumatoid arthritis \nT cells also interact with synovial fibroblasts (synoviocytes) through TNF-α, converting synovium into a thick, abnormal layer of granulation tissue known as \npannus\n. \n4. \nThree patterns of bone destruction by bone tumors have been identified: (1) the geographic pattern, (2) the moth-eaten pattern, and (3) the \npermeative\n pattern\n. \n\nCH44S54\nRheumatoid Arthritis\n(1 of 5)\nRheumatoid arthritis (RA): Inflammatory joint disease\nSystemic autoimmune destruction to synovial membrane and joints\nPresence of rheumatoid factors (RFs): RA or RF test\nAntibodies (immunoglobulin G [IgG] and IgM) against antibodies; sometimes IgA\nJoint fluid with inflammatory exudate\nRupture of cyst or synovial joint\n54\nSpeaker notes: \n\nCH43S28\nMaintenance of Bone Integrity\n(2 of 3)\nRepair: Bone heals itself\nHematoma formation\nClot forms.\nProcallus formation\nProduces granulation tissue.\nCallus formation\nForms membranous or woven bone.\nCallus replacement\nReplaces the callus with lamellar bone or trabecular bone.\nRemodeling\nPeriosteal and endosteal surfaces are remodeled to the size and shape of the bone before the injury.\n28\nSpeaker notes: \n\nCH44S39\nInfectious Bone Disease: Osteomyelitis\n(1 of 3)\nIs usually caused by a \nStaphylococcus aureus\n infection.\nIs often outside the body (exogenous); can be from a bloodborne (endogenous) infection.\nInfection spreads under the periosteum and along the bone shaft or into the bone marrow.\nIn adults: Affects the cortex \nSequestra: Sections of dead bone from periosteal separation\nInvolucrum: Periosteal new bone\nAcute vs. \nsubacute\n vs. chronic\n39\nSpeaker notes: \n\nCH44S62\nGout\n(1 of 6)\nIs a metabolic disorder that disrupts the body’s control of uric acid production or excretion.\nExhibits high levels of uric acid in the blood and other body fluids.\nOccurs when the uric acid concentration increases to high enough levels to crystallize. \nCrystals deposit in connective tissues throughout the body.\nIf prolonged in joints: Gouty arthritis\nTophi: Small, white visible nodules\n62\nSpeaker notes: ",
