   "evidenceExcerpt": "CH44S54\nRheumatoid Arthritis\n(1 of 5)\nRheumatoid arthritis (RA): Inflammatory joint disease\nSystemic autoimmune destruction to synovial membrane and joints\nPresence of rheumatoid factors (RFs): RA or RF test\nAntibodies (immunoglobulin G [IgG] and IgM) against antibodies; sometimes IgA\nJoint fluid with inflammatory exudate\nRupture of cyst or synovial joint\n54\nSpeaker notes: \n\nCH44S55\nRheumatoid Arthritis\n(2 of 5)\nClinical manifestations\nSymmetric joint swelling, joint deformities\nSystemic manifestations of inflammation\nRheumatoid nodules in organs\nCaplan syndrome\nPainful, tender, stiff joints\n55\nSpeaker notes: \n\nCH44S56\nRheumatoid Arthritis\n(3 of 5)\nEvaluation \nAmerican College of Rheumatology (ACR) changed classification system in 2010\nDiagnosis dependent on physical exam and serology evaluation of RF/ACPA\nSerum markers can be present for years to decades before recognized.\n56\nSpeaker notes: \n\nCH44S21\nSupport Structure Trauma\n(2 of 3)\nPathophysiology\nInflammatory exudate develops between the torn ends.\nGranulation tissue grows inward, and then collagen formation begins 3–4 days after injury.\nVascular fibrous tissue fuses the new and surrounding tissues into a single mass.\nHealing tendon or ligament lacks sufficient strength to withstand a strong pull for 4–5 weeks after the injury.\n21\nSpeaker notes: \n\nCH44S49\nOsteoarthritis\n(1 of 4)\nCommon age-related disorder of synovial joints\nInflammatory joint disease\nLoss of articular cartilage, sclerosis of underlying bone, and formation of bone spurs (osteophytes)\nAlso called degenerative joint disease.\nIncidence increases with age.\n49\nSpeaker notes: \n\nCH44S65\nGout\n(4 of 6)\nClinical manifestations\nPain in the great toe (usually, but not always): Worse at night\n Increase in serum urate concentration: Hyperuricemia\nRecurrent attacks of monoarticular arthritis: Inflammation of a single joint\nDeposits of monosodium urate monohydrate (tophi) in and around the joints\nRenal disease, involving glomerular, tubular, and interstitial tissues and blood vessels\nFormation of renal stones\n65\nSpeaker notes: ",
