   "evidenceExcerpt": "CH44S59\nAnkylosing Spondylitis\n(1 of 3)\nChronic inflammatory joint disease of the spine or sacroiliac joints, causing stiffening and fusion of the joints\nUnknown cause but strong association with human leukocyte antigen B27 (\nHLA-B27\n)\nAffects peripheral joints of \nappendicular\n skeleton.\n59\nSpeaker notes: \n\nCH44S60\nAnkylosing Spondylitis\n(2 of 3)\nClinical manifestations\nLow back pain, stiffness, pain, and restricted motion, \nLoss of normal lumbar curvature\nKyphosis\nChest pain/restricted chest movement\nFibrotic changes to organs\n60\nSpeaker notes: \n\nCH41S64\nInflammatory Bowel Disease\n(5 of 8)\nCrohn disease\nGranulomatous colitis, ileocolitis, or regional enteritis\nIdiopathic inflammatory disorder; affects any part of the digestive tract, from mouth to anus\nDifficult to differentiate from ulcerative colitis\nSimilar risk factors and theories of causation\nStrong association\nNucleotide-binding oligomerization domains (\nCARD15\n/\nNOD2\n) gene mutations\n64\nSpeaker notes: \n\nCH42S34\nCystic Fibrosis\n(1 of 3)\nIs a genetically transmitted disease (dysfunction of the CFTR protein) that involves many organs and systems.\nUsually causes death in childhood or young adulthood.\nDeficiency of pancreatic enzymes in the digestive tract \nResult of overproduction of extremely viscous mucus and pancreatic enzyme deficiency\n34\nSpeaker notes: \n\nCH45S47\nDuchenne Muscular Dystrophy\n(1 of 5)\nMost common muscular dystrophy\nX-linked recessive inheritance (males only)\nDeletion of exons of DMD gene on the X chromosome or a nonsense mutation resulting in termination of translation\nDuchenne muscular dystrophy gene\nEncodes for the dystrophin protein.\n47\nSpeaker notes: ",
