   "explain": "The packet links gout to purine metabolism.",
   "decision": "purine",
   "evidenceExcerpt": "CH44S63\nGout\n(2 of 6)\nRelated to purine metabolism \nCauses\nPurine\n synthesis or breakdown is accelerated.\nPoor uric acid secretion in the kidneys \nMechanisms for crystal deposition\nLow body temperatures\nDecreased albumin or glycosaminoglycan levels\nChanges in ion concentration and pH\nTrauma\n63\nSpeaker notes: \n\nCH40S41\nIntestinal Digestion and Absorption\n(5 of 9)\nProteins\nPancreatic enzymes accomplish major protein hydrolysis in the small intestine.\nTrypsin and chymotrypsin: Hydrolyze the interior bonds of the large molecules (endopeptidases).\nCarboxypeptidase: Breaks away the end amino acids (exopeptidase).\nSodium-dependent carrier actively transports amino acids from the cytosol into the bloodstream.\nFree amino acids can be absorbed directly from the intestinal lumen using a membrane transport protein.\n41\nSpeaker notes: \n\nCH40S63\nSecretion of Bile\n(2 of 2)\nEnterohepatic circulation\nRecycling of bile salts\nAlso called choleresis\nCholeretic agent: Substance that stimulates the liver to secrete bile\nStrong stimulus: High concentration of bile salts\nOther choleretic agents: Secretin, cholecystokinin, vagal stimulation\n63\nSpeaker notes: \n\nCH43S18\nBone Matrix\n(2 of 4)\nCollagen fibers\nAre essential for bone strength.\nForm fibrils that twist. \nAre synthesized and secreted by osteoblasts.\nHave over 20 types: All their functions are not yet known.\n18\nSpeaker notes: ",
