   "explain": "Released myoglobin is the pigment causing dark urine in rhabdomyolysis.",
   "decision": "pigment",
   "evidenceExcerpt": "CH44S27\nRhabdomyolysis\n(1 of 3) \nLife-threatening complication of severe muscle trauma with muscle cell loss \nCrush syndrome vs. crush injuries\nCompartment syndromes\nRapid breakdown of muscle that causes the release of intracellular contents\nProtein pigment myoglobin into extracellular space and bloodstream\n27\nSpeaker notes: \n\nCH44S28\nRhabdomyolysis\n(2 of 3) \nClassic triad\nMuscle pain, weakness, and dark urine (from myoglobin)\nTreatment\nRapid intravenous hydration: To maintain adequate kidney flow\nHyperkalemia: May require temporary \nhemodialysis\n.\n28\nSpeaker notes: \n\nCH40S64\nMetabolism of Bilirubin\n(1 of 2)\nIs a byproduct of the destruction of aged red blood cells.\nGives bile a greenish black color and produces the yellow tinge of jaundice.\nUnconjugated (free) bilirubin: Is lipid soluble.\nConjugated bilirubin: Is water soluble.\nUrobilinogen\nIn the ileum and colon, conjugated bilirubin is deconjugated by bacteria and then converted.\nGives urine its yellow color; feces its brown color.\n64\nSpeaker notes: \n\nCH40S65\nMetabolism of Bilirubin\n(2 of 2)\nQuestion 5\nWhat substance is located in the sinusoids of the liver that removes bacteria from the blood in the hepatic circulation? \nConjugated bilirubin\nKupffer cells \nCholeretic agents\nBile \n65\nSpeaker notes: Elsevier items and derived items © 2009, 2005, 2001 by Saunders, an imprint of Elsevier Inc.\n65\nANS: \n2\nKupffer\n cells (macrophages) in the sinusoids of the liver remove bacteria and foreign particles from blood in the hepatic circulation.\n \n1. In the liver, unconjugated bilirubin moves from plasma in the sinusoids into the hepatocyte. Within hepatocytes it joins with glucuronic acid to form conjugated bilirubin, which is water soluble. \n3. A choleretic agent is a substance that stimulates the liver to secrete bile.\n4. \nBile helps emulsify fats.\n \n\nCH43S64\nTests of Muscular Function\n(1 of 2)\nSerum creatine kinase\nIs increased when muscles are diseased or damaged. \nMyoglobin\nIs detectable in urine with acute muscle damage.\nElectromyogram (EMG)\nUses sensitive needle electrodes; the summation of action potentials of the muscle is recorded.\nHelps differentiate muscle diseases (myopathy) from peripheral nerve (neuropathy) and neuromuscular junction disorders.\n64\nSpeaker notes: ",
