   "evidenceExcerpt": "CH44S28\nRhabdomyolysis\n(2 of 3) \nClassic triad\nMuscle pain, weakness, and dark urine (from myoglobin)\nTreatment\nRapid intravenous hydration: To maintain adequate kidney flow\nHyperkalemia: May require temporary \nhemodialysis\n.\n28\nSpeaker notes: \n\nCH41S84\nAscites\n(4 of 5)\nTreatment\nDietary salt restriction\nPotassium-sparing diuretics \nStrong diuretics, such as furosemide or ethacrynic acid\nVasopressin receptor 2 antagonists: For dilutional hyponatremia\nPossible administration of albumin\nMonitor serum electrolytes, especially sodium and potassium\n84\nSpeaker notes: \n\nCH42S54\nNecrotizing Enterocolitis\n(4 of 4)\nTreatment\nCessation of feeding formula milk\nGastric suction: To decompress the intestines\nMaintenance of fluid and electrolytes\nAdministration of antibiotics: To control sepsis\nSurgical resection\n54\nSpeaker notes: ",
