   "evidenceExcerpt": "CH44S75\nMuscle Membrane Abnormalities\n(1 of 2)\nMyotonia\nMuscle relaxation is delayed after voluntary contractions.\nDisabling muscle stiffness \nWeakness\nSeen mostly in inheritable disorders.\nTreatment\nDrugs that reduce muscle fiber excitability\nCentral core disease\nSymmetric proximal muscle weakness\nSeen in infancy.\nDiagnosed through muscle biopsy\n75\nSpeaker notes: \n\nCH44S21\nSupport Structure Trauma\n(2 of 3)\nPathophysiology\nInflammatory exudate develops between the torn ends.\nGranulation tissue grows inward, and then collagen formation begins 3–4 days after injury.\nVascular fibrous tissue fuses the new and surrounding tissues into a single mass.\nHealing tendon or ligament lacks sufficient strength to withstand a strong pull for 4–5 weeks after the injury.\n21\nSpeaker notes: \n\nCH44S27\nRhabdomyolysis\n(1 of 3) \nLife-threatening complication of severe muscle trauma with muscle cell loss \nCrush syndrome vs. crush injuries\nCompartment syndromes\nRapid breakdown of muscle that causes the release of intracellular contents\nProtein pigment myoglobin into extracellular space and bloodstream\n27\nSpeaker notes: \n\nCH44S74\nDisuse Atrophy\nNormal size of muscle fibers are reduced as a result of prolonged inactivity.\nBed rest, trauma, casting, space flight or local nerve damage\nOxidative stress causes decreased protein synthesis and increased proteolysis.\nPrevention and treatment\nForceful isometric movements and passive lengthening exercises, adequate nutrition\n74\nSpeaker notes: ",
