   "evidenceExcerpt": "CH45S6\nBone Formation\n(1 of 2)\nBone formation begins in two phases at approximately 6 weeks’ gestation.\nDelivery of bone cell precursors to sites of bone formation\nAggregation of the bone cell precursors at the primary centers of ossification\nAre mature and begin to secrete osteoid.\nOssification occurs in two long bone centers.\nPrimary center: Diaphysis—long, central portion of bone\nSecondary center: Epiphysis—end portions of bone\n6\nSpeaker notes: \n\nCH45S7\nBone Formation\n(2 of 2)\nIntramembranous formation\nOn or within the mesenchyme\nEndochondral\n formation\nDevelopment of new bone from cartilage \nCartilage anlage\nPerichondrium\nPeriosteal collar\nSecondary centers of ossification\n7\nSpeaker notes: \n\nCH45S8\nBone Growth\n(1 of 2)\nUntil adult stature is achieved, bone growth occurs at the \nphyseal\n plate through endochondral ossification.\nBone is being constantly destroyed and re-formed. \nEpiphyseal closure\nUnites the metaphysis and the epiphysis.\nOccurs earlier in girls than in boys because of earlier puberty in girls.\n8\nSpeaker notes: ",
