   "evidenceExcerpt": "CH45S12\nMuscle Growth\n(1 of 2)\nBetween birth and maturity, muscle nuclei in the body increase 14 times in boys and 10 times in girls.\nComposition and size of muscles vary with age.\nGrowth in length occurs at the ends of muscles.\nIncrease in length is accompanied by an increase in the number of nuclei in the fibers.\nMuscle fibers increase in diameter as the fibrils become more numerous.\nFibrils themselves do not increase in diameter.\n12\nSpeaker notes: \n\nCH45S13\nMuscle Growth\n(2 of 2)\nInfants\nMuscle: Approximately 25% of the total body weight (40% in adults) is in muscle.\nMajority of weight: Is in the axial musculature (55% in an adult’s lower limbs).\nRespiratory and facial muscles are well developed at birth.\nFor breathing and sucking\nOther muscle groups, such as the pelvic muscles, take several years to develop. \n13\nSpeaker notes: \n\nCH43S42\nStructure and Function of Skeletal Muscles\n(4 of 4)\nMillions of individual muscle fibers contract and relax to facilitate movement.\nComposition: 75% water, 20% protein, 5% organic and inorganic compounds\nOver 350 named muscles; most are paired\nAre 2–60 cm long.\n42\nSpeaker notes: ",
