   "evidenceExcerpt": "CH45S9\nBone Growth\n(2 of 2)\nFactors affecting bone growth\nGrowth hormone (secreted by the pituitary)\nNutrition\nGeneral health\nMany growth factors and regulators: Fibroblast growth factor\nPeak bone mass is achieved by the middle to late 20s.\n9\nSpeaker notes: \n\nCH40S28\nGastric Secretion\n(4 of 7)\nStimulates hydrochloric acid\nAcetylcholine\nCaffeine\nCalcium\nGherlin\nGastrin\nHistamine\nInhibits hydrochloric acid\nAtrial natriuretic peptide\nCholecystokinin\nGlucagon-like peptide-1\nSomatostatin\nSecretin\nProstaglandins\n28\nSpeaker notes: \n\nCH40S33\nSmall Intestine\n(2 of 5)\nPeritoneum\nSerous membrane surrounding the organs of the abdomen and lining the abdominopelvic cavity\nVisceral peritoneum lies on the surface of the organs.\nParietal peritoneum lines the wall of the body cavity.\nPeritonitis is inflammation of the peritoneum.\nPeritoneal cavity\nIs the space between the visceral and parietal peritoneum.\n33\nSpeaker notes: \n\nCH40S34\nSmall Intestine\n(3 of 5)\nMuscle layers\nOuter: Longitudinal\nInner: Circular \nMucosal folds\nVilli \nFunction:  Absorption\nMicrovilli\nBrush border\nGreatly increases absorption surface area\n34\nSpeaker notes: ",
