   "evidenceExcerpt": "CH45S15\nDevelopmental Dysplasia of the Hip\n(1 of 5)\nFormerly: Congenital dislocation of the hip\nAbnormality of the proximal femur, acetabulum,\nor both\nRisk factors\nFamily history, female, metatarsus adductus, torticollis, oligohydramnios, first pregnancy, breech presentation\nSubluxated or dislocated or acetabular dysplasia\n15\nSpeaker notes: \n\nCH45S16\nDevelopmental Dysplasia of the Hip\n(2 of 5)\nClinical manifestations\nAsymmetry of gluteal or thigh folds\nLimb length discrepancy: Galeazzi sign\nLimitation of hip abduction\nPositive Ortolani sign: Hip dislocated but reducible\nPositive Barlow maneuver: Hip reduced but dislocatable\nPositive Trendelenburg gait: Waddling\nPain: Very late\n16\nSpeaker notes: ",
