   "tier": 1,
   "pool": "mock",
   "explain": "The packet specifies the Pavlik harness for infants under four months.",
   "decision": "harness",
   "evidenceExcerpt": "CH45S17\nDevelopmental Dysplasia of the Hip\n(3 of 5)\nTreatment\nThe earlier the treatment is begun—usually before 1 year of age—the better the result.\nIn children younger than 4 months of age: Pavlik harness\nUp to 12 months of age: Closed reduction (without opening the joint), followed by spica or body casting for up to 3 months\n17\nSpeaker notes: \n\nCH45S18\nDevelopmental Dysplasia of the Hip\n(4 of 5)\nTreatment (cont.)\nAfter 12 months of age: Surgical intervention, including opening the joint and cutting and realigning the femur \nand/or acetabulum\nAs the child ages: Failure of good outcomes\nUp to 70% of children treated surgically after 3 years of age develop early osteoarthritis.\n18\nSpeaker notes: \n\nCH45S19\nDevelopmental Dysplasia of the Hip\n(5 of 5)\nQuestion 1\nAn infant has a positive Ortolani sign. Which condition is the infant experiencing? \nSyndactyly \nDevelopmental dysplasia of the hip \nGenu varum\nPeriosteal collar\n \n19\nSpeaker notes: Elsevier items and derived items © 2009, 2005, 2001 by Saunders, an imprint of Elsevier Inc.\n19\nANS: \n2\nA\n p\nositive Ortolani sign (hip dislocated, but reducible) occurs in developmental dysplasia of the hip\n. \n1. The most common congenital defect of the upper extremity is syndactyly, or webbing of the fingers. \n3. Genu varum (bowleg) reaches a peak by 30 months of age. \n4. The perichondrium contains cells that develop into osteoblasts, forming a collar of bone, termed the periosteal collar, around the cartilage model. ",
