   "evidenceExcerpt": "CH45S39\nOsteochondroses\n(3 of 7)\nLegg-Calvé-Perthes disease (Perthes disease)\nBlood supply to the femoral head is interrupted.\nIs a self-limiting disease.\nOssification center first becomes necrotic, collapses, and then is gradually remodeled by live bone.\nClinical manifestations\nKnee pain\nSpasm on inward rotation of the hip and a limitation of internal rotation flexion and abduction\nAbnormal gait: Trendelenburg gait or abductor lurch\n39\nSpeaker notes: \n\nCH45S40\nOsteochondroses\n(4 of 7)\nLegg-Calvé-Perthes disease (Perthes disease) (cont.)\nTreatment\nContainment: Keep the ball completely in the socket. \nMotion: Maintain articular cartilage.\nAdminister antiinflammatory medications and use crutches:  For episodes of synovitis and activity modification\nAvoid jumping activities that place increased stress on the hip during the active phase.\nSerial roentgenograms: To monitor hip placement.\nIntraarticular\n injection of bisphosphonates: To reduce the function of \nosteoclasts\n.\nSurgery may be necessary.\n40\nSpeaker notes: ",
