   "evidenceExcerpt": "CH45S41\nOsteochondroses\n(5 of 7)\nOsgood-Schlatter disease\nTendinitis of the anterior patellar tendon and osteochondrosis of the tubercle of the tibia\nMild tendinitis to a complete separation of the anterior extension of the tibial epiphysis\nClinical manifestations\nPain and swelling in the affected area, becoming prominent and tender to direct pressure, especially after physical activity\n41\nSpeaker notes: \n\nCH45S42\nOsteochondroses\n(6 of 7)\nOsgood-Schlatter disease (cont.)\nTreatment\nRestriction from strenuous physical activity: 4–8 weeks \nIf pain relief is not achieved: Cast or brace\nReturn to unrestricted athletic participation: Another 8 weeks\n42\nSpeaker notes: ",
