   "explain": "Infant vessels perforate the plate and connect regions.",
   "decision": "infection spread",
   "evidenceExcerpt": "CH45S29\nOsteomyelitis\n(1 of 5)\nInfection in the bone\nIs often associated with septic arthritis because an infant’s bone has blood vessels that perforate the growth plate.\nBegins as a bloody abscess in the metaphysis of the bone.\nVertebrae may be involved in adolescents and adults.  \nThese age groups are affected less often than younger populations.\n29\nSpeaker notes: \n\nCH45S30\nOsteomyelitis\n(2 of 5)\nInfection spreads under the periosteum and along the bone shaft or into the bone marrow. \nSequestra\nSections of dead bone from periosteal separation\nInvolucrum\nPeriosteal new bone\nSecondary septic arthritis\nPus of ruptured joint causes inflammation\n30\nSpeaker notes: \n\nCH45S31\nOsteomyelitis\n(3 of 5)\nIs significantly less common after the epiphyseal plates are closed, except in the vertebral body.\nInfection may develop in any part of a bone, and abscesses spread slowly.\nDestruction of the cortex in a localized area may result in a pathologic fracture. \n31\nSpeaker notes: \n\nCH45S32\nOsteomyelitis\n(4 of 5)\nClinical manifestations\nInfants\nFever and failure to move the affected limb (pseudoparalysis)\nChildren\nFever and systemic signs of toxicity\nSwelling, fever, tenderness, and decreasing ability to bear weight on or move the affected area\nOnset can be abrupt.\nAdolescents\nBack pain for several weeks: May be the only complaint.\n32\nSpeaker notes: \n\nCH45S33\nOsteomyelitis\n(5 of 5)\nTreatment\nIntravenous (IV) antibiotics or, in highly reliable children and families, a combination of IV and oral antibiotics for 6 weeks\nDrainage and margination of bone: For abscess\nImmobilization: Pain control\nIf a joint is infected (septic arthritis): It is a surgical emergency: Lysozymes released from the involved \nneutrophils\n cause damage to the articular cartilage.\n33\nSpeaker notes: ",
