   "decision": "tumor location",
   "evidenceExcerpt": "CH45S55\nMalignant Bone Tumors\n(1 of 3)\nOsteosarcoma\nOriginates from bone-producing \nmesenchymal\n cells.\nMakes \nosteoid\n tissue.\nDeletion of genetic material on the long arm of chromosome 13\nMost occurring between 10 and 18 years of age\nClinical manifestations\nPain\nTreatment\nSurgery and multiagent chemotherapy \nRadiation\n55\nSpeaker notes: \n\nCH45S56\nMalignant Bone Tumors\n(2 of 3)\nEwing sarcoma\nMalignant round cell tumor of bone and soft tissue\nMost lethal malignant bone tumor that can occur during childhood\nOccurs in the diaphysis of the long bones or in flat bones.\nClinical manifestations\nPain, soft tissue mass, fever, malaise, anorexia\nTreatment\nPreoperative chemotherapy, followed by radiation or surgical resection, or both, with continuation of chemotherapy for 12–18 months\nSurgical resection: Essential \n56\nSpeaker notes: \n\nCH44S44\nBone Tumors\n(3 of 6)\nOsteosarcoma\n38% of bone tumors\nPredominant in adolescents and young adults; occurs in seniors with a history of radiation therapy\nContain masses of osteoids: Bone-forming tumors \nStreamers: Noncalcified bone matrix and callus\nLocation: In the metaphyses of the long bones\n50% occur around the knees\nClinical manifestations\nPain and swelling\nTreatment\nSystemic chemotherapy and surgery \n44\nSpeaker notes: ",
