   "evidenceExcerpt": "CH45S34\nJuvenile Arthritis\n(1 of 3)\nJuvenile idiopathic arthritis (JIA): Childhood form of rheumatoid arthritis\nBasic \npathophysiology\n: Same as adult form\nOne difference: Mode of onset\nFewer than five joints: Pauciarticular arthritis\nMore than five joints: Polyarticular arthritis\nSystemic: Still disease\n34\nSpeaker notes: \n\nCH45S35\nJuvenile Arthritis\n(2 of 3)\nDifferences in JIA and adult rheumatoid arthritis (RA)\nLarge joints are affected.\nSpinal changes include subluxation and ankylosis of the cervical spine.\nJoint pain is not as severe.\nAntinuclear antibody test is positive.\nChronic uveitis is common.\n35\nSpeaker notes: ",
