   "evidenceExcerpt": "CH45S35\nJuvenile Arthritis\n(2 of 3)\nDifferences in JIA and adult rheumatoid arthritis (RA)\nLarge joints are affected.\nSpinal changes include subluxation and ankylosis of the cervical spine.\nJoint pain is not as severe.\nAntinuclear antibody test is positive.\nChronic uveitis is common.\n35\nSpeaker notes: \n\nCH45S36\nJuvenile Arthritis\n(3 of 3)\nDifferences in JIA and adult rheumatoid arthritis (RA) (cont.)\nRheumatoid factor is seldom detected.\nRheumatoid nodules are common in the heart, lungs, eyes, and other organs.\nIs positive for cyclic citrullinated peptide antibody. \nTreatment: Supportive, biologics\n36\nSpeaker notes: ",
