   "evidenceExcerpt": "CH45S26\nScoliosis\n(1 of 3)\nRotational curvature of the spine\nNonstructural\nCurvature from a cause other than the spine\nStructural \nCurvature associated with vertebral rotation\nSkeletal abnormalities, neuromuscular disease, trauma, extraspinal contractures, bone infections of the vertebrae, metabolic bone disorders, joint disease, and tumors\nIdiopathic\nNo known cause\nOnset: Infant, juvenile, adolescent\n26\nSpeaker notes: \n\nCH45S27\nScoliosis\n(2 of 3)\nClinical manifestations (cont.)\nNonstructural scoliosis: Mild spinal curvature with prominence of one hip or rounded shoulders\nStructural scoliosis: Asymmetry of hip height, asymmetry of shoulder height, shoulder and scapular (shoulder blade) prominence, and rib prominence\nTreatment\nBracing: Prevents progression, does not cure\nSurgical fusion of spine\n27\nSpeaker notes: \n\nCH45S28\nScoliosis\n(3 of 3)\nQuestion 2\nStructural scoliosis may be caused by:\nneuromuscular disease.\npostural abnormalities.\ndiscrepant leg length. \nvitamin C deficiency.\n \n28\nSpeaker notes: Elsevier items and derived items © 2009, 2005, 2001 by Saunders, an imprint of Elsevier Inc.\n28\nANS: \n1\nStructural scoliosis can be caused by a great variety of conditions. It can result from congenital skeletal abnormalities (15%), neuromuscular diseases (15%), trauma, extraspinal contractures, bone infections that involve the vertebrae, metabolic bone disorders (e.g., rickets, osteoporosis, osteogenesis imperfecta), joint disease, and tumors.\n2. Postural abnormalities cause nonstructural scoliosis. \n3. Discrepant leg length causes nonstructural scoliosis. \n4. Vitamin D deficiency (rickets) may produce structural scoliosis.\n ",
