   "evidenceExcerpt": "CH45S44\nNeuromuscular Disorders\nGroup of inherited disorders that cause degeneration of skeletal muscle fiber.\nCause progressive, symmetric weakness, and wasting of skeletal muscle groups.\n44\nSpeaker notes: \n\nCH45S45\nCerebral Palsy\n(1 of 2)\nNonprogressive disorder of movement and posture caused by injury or malformation of developing CNS.\nDisease patterns\nHemiplegia, diplegia, quadriplegia \nClinical manifestations\nMotor milestones are not met\n45\nSpeaker notes: \n\nCH45S46\nCerebral Palsy\n(2 of 2)\nTreatment\nNo cure: Multidisciplinary approach; surgery\nPhysical and occupational therapies, orthotics, spasticity reduction (selected dorsal rhizotomy, baclofen), botulinum-A (Botox) toxin injections\n46\nSpeaker notes: \n\nCH45S47\nDuchenne Muscular Dystrophy\n(1 of 5)\nMost common muscular dystrophy\nX-linked recessive inheritance (males only)\nDeletion of exons of DMD gene on the X chromosome or a nonsense mutation resulting in termination of translation\nDuchenne muscular dystrophy gene\nEncodes for the dystrophin protein.\n47\nSpeaker notes: \n\nCH45S48\nDuchenne Muscular Dystrophy\n(2 of 5)\nX-linked recessive inheritance (males only) (cont.)\nDystrophin mediates the anchorage of the actin cytoskeleton of the skeletal muscle fiber to the basement membrane.\nPoorly anchored fibers tear apart under the repeated stress of contraction; free calcium then enters the muscle cells, causing \ncell death and fiber necrosis.\n48\nSpeaker notes: \n\nCH45S49\nDuchenne Muscular Dystrophy\n(3 of 5)\nClinical manifestations appear by 3 or 4 years of age.\nGait abnormalities\nProgressive weakness\nMuscles\nRespiratory insufficiency\nCardiomyopathy\nScoliosis\nWaddling gait\nGower sign: Climbing up the legs when rising\nCognitive dysfunction\n49\nSpeaker notes: ",
