   "decision": "false size",
   "evidenceExcerpt": "CH45S61\nUnit XIII: Musculoskeletal System\nCase Study\nDiscussion Questions\n(1 of 2)\nDuchenne muscular dystrophy is the most common of the muscular dystrophies and occurs only in boys. It is a progressive weakness associated with large calf muscles that are said to be:\nequinovariant\n.\npseudohypertrophic\n.\nfacioscapulohumeral\n.\nosteochondromatic\n.\n61\nSpeaker notes: ANS: B\nConsisting of fat and connective tissue rather than of muscle, the large calf muscles of a boy with \nDuchenne\n muscular dystrophy are \npseudohypertrophic\n. \nEquinovariant\n refers to a position of the feet when walking. Children with Duchenne muscular dystrophy have feet that look as if they have been rotated internally at the ankle. \nFacioscapulohumeral\n is a form of muscular dystrophy that begins with weakness and atrophy of facial and shoulder girdle muscles. Osteocondroma is a very common benign tumor that results in a bony protuberance of bone, growing near the growth plate.\n61",
