   "id": "case-nu545-u6-ch40-case-01",
   "dom": "digestive",
   "title": "Chapter 40 · released example 1",
   "stem": "SOURCE TIMELINE: 13 weeks gestation and approximately 10 weeks until delivery conflict. Timing is not tested.\n\nA 28-year-old pregnant woman is seen in her obstetrician’s office for a routine appointment during her 13th week of gestation. This is her second pregnancy, and she has been feeling tired. The baby is measuring large for gestational age, and she states that the baby has been giving her heartburn. She is craving spicy, Mexican food and cannot get enough of chips and salsa. The obstetrician reminds the young woman that she still has approximately 10 weeks until delivery. He reminds her to continue to take her vitamins and iron supplements and to cut back on the spicy foods, especially before bedtime, to decrease the incidence of heartburn or gastroesophageal reflux.",
   "src": [
    "CH40CASE1"
   ],
   "scopeNote": "SOURCE TIMELINE: 13 weeks gestation and approximately 10 weeks until delivery conflict. Timing is not tested.",
   "items": [
    {
     "id": "nu545-u6-ch40-case-01",
     "rootId": "nu545-u6-ch40-case-01",
     "c": "nu545-e6-c40-motility",
     "sec": "ch40",
     "dom": "digestive",
     "t": "teach",
     "q": "In the digestive system, the stomach is stimulated by eating to produce large volumes of gastric secretions. The secretion that is responsible for converting pepsinogen to pepsin and acts as a bactericide against swallowed organisms is:\n\n1. Gastroferrin\n2. Hydrochloric acid\n3. Intrinsic factor\n4. Chymotrypsin",
     "model": "SOURCE TIMELINE: 13 weeks gestation and approximately 10 weeks until delivery conflict. Timing is not tested.\n\nIn the digestive system, the stomach is stimulated by eating to produce large volumes of gastric secretions. The secretion that is responsible for converting pepsinogen to pepsin and acts as a bactericide against swallowed organisms is:\n\n2. Hydrochloric acid\n\nGastric hydrochloric acid dissolves food particles, acts as a bactericide against swallowed organisms, and converts pepsinogen to pepsin. Gastroferrin facilitates small intestinal absorption of iron. Intrinsic factor is secreted throughout the gastric mucosa and is necessary for intestinal absorption of vitamin B12. Chymotrypsin is a pancreatic enzyme that hydrolyzes proteins in the small intestines.",
     "s": [
      "CH40CASE1"
     ],
     "pool": "released",
     "eligible": false,
     "tier": 1
    }
   ]
