 "SOURCE_ISSUES": "# Unit 6 source adjudication\nOriginal packet records remain untouched. These are build decisions, not corrections to the source.\n\n| Evidence | Issue | Handling |\n|---|---|---|\n| Ch40 course case introduction | 13th gestational week conflicts with approximately 10 weeks remaining | Preserve in private intake and source self-check disclosure; do not test timing. |\n| Ch43 case2 | Supplied key Gomphosis contradicts its own Syndesmosis definition | Unscored self-check, explicit annotated conflict. Instructor-corrected key still needed. |\n| Ch41 case1 vs slide62 | Small-volume inflammatory diarrhea answer vs large-volume watery UC wording | No scored volume-based inflammatory discriminator. |\n| Ch44 course page title | Says children; deck is general/adult alterations | Display deck title in lab; retain source-page title in provenance. |\n| Ch40 slides11–12,14 | Plexus location and salivary autonomic wording warrant source clarification | Do not grade those locations/directions. IgA and amylase remain supported. |\n| Ch40 slide42,73 | Cholesterol ester products and proenzyme activation wording ambiguous | Do not teach a repaired pathway from memory; gate these specific details. |\n| Ch40 slide59 | Cell-function indentation can attach phagocytosis to stellate cells | Use slide65 notes explicitly identifying Kupffer macrophage function; do not flatten this list into a new relationship. |\n| Ch40 slide67 | Glycogen-storage term appears as glyconeogenesis | Teach storage without testing that word. |\n| Ch41 slide11 | Mixed vomiting-treatment list needs clarification | Drug-selection keys excluded. |\n| Ch41 slide125 | Hepatitis A listed in liver cancer risks | Viral cancer-risk list excluded pending textbook/instructor check. |\n| Ch42 slide38–39 | Broad oats/malt grouping and meconium ileus under celiac manifestations | Exclude these specific claims; retain autoimmune villous injury and gluten-free treatment. |\n| Ch42 slide60 and notes | Nutrition labels/options conflict; supplied note keys option2 with different disease wording | Preserve as provenance-only source evidence, no scored item. |\n| Ch42 slide63 | Phototherapy labeled ultraviolet | Wavelength claim excluded; no replacement wavelength added. |\n| Ch42 slide68 vs slide67 | No-curative-therapy blanket statement vs antiviral effectiveness | Exclude blanket prognosis/treatment absolutes. |\n| Ch43 slide17 | Composition percentages do not give a coherent shared denominator | No numerical matrix-composition question. |\n| Ch43 slide44 | Endomysium/fascicle relation needs confirmation | No scored connective-sheath hierarchy item. |\n| Ch43 slide52 vs64 | Creatinine/creatine kinase ambiguity; no muscle-mass association | Prompt26 is Missing. Injury CK sourced to slide64 only. |\n| Ch44 slides30,33,36 | Poor mineralization used for osteoporosis; later normal histology contrasted with osteomalacia | Use low mass/resorption imbalance, gate mineralization wording and absolute density cutoffs. |\n| Ch44 slide37 | Hyperthyroidism wording in osteomalacia treatment | Exclude; request exact endocrine wording. |\n| Ch45 slide34 | Fewer/more than five joints leaves exactly five undefined | No exact subtype count threshold tested. |\n| Ch45 slide36 | Broad antibody/nodule claims lack qualification | Exclude from scored originals. |\n| Ch45 slides47–51,61 | Males-only absolute; conflicting calf enlargement explanation | Test dystrophin and contraction injury; use slide61 notes for pseudohypertrophy. No sex-exclusive or true-hypertrophy key. |\n| Ch45 slide40 | Intraarticular bisphosphonate treatment detail | Exclude pending exact instructor/textbook confirmation. |\n\nNo external medical facts were used to repair these records. These holds identify uncertainty; not every flagged passage has been proven wrong. Obtain the assigned ninth-edition passages for the exact study-guide gaps in coverage.md.\n",
