    "promptVerbatim": "Anatomy and function of the GI system components; normal intestinal flora",
    "status": "Partial",
    "supported": "The digestive tract moves material from mouth to anus while accessory organs supply secretions. Mucosa, submucosa, muscularis and outer covering provide distinct layers. Villi and microvilli enlarge the absorbing surface; the large intestine recovers water and electrolytes. Acid, bile, movement and antibodies help shape the microbial distribution. The liver processes absorbed nutrients; the gallbladder stores and concentrates bile; the exocrine pancreas supplies enzymes and alkaline fluid.",
